// The Guide (#48): one card per feature of the app, in English and Italian. Keep it current: every user-facing
// change updates its card in the same change, and `npm run check:guide` fails when a tab or a console command has
// no card or line, or a text misses a language (tools/check-guide.mjs).
// Inline marks in texts: [Label] is a button of the app, {K} a key.
//   id: card id; tab: the tab it lives in (null for parts of the app outside the tabs); mode: 'ascolta' | 'lab';
//   show: CSS selector of the control "Show me" flashes; what, how, know: texts; parts: sub-sections (the Radio).

export const GUIDE = [
  {
    id: 'modes', tab: null, mode: null, show: '.modes',
    title: { en: 'Two modes', it: 'Due modalità' },
    what: { en: 'The app has two modes. Listen is for music: Compose, Songs, Playlists, Radio. Groove Lab is for building and learning: Artists, Styles, Genres, Sounds, Patterns, Guide, Strudel lessons, References.', it: 'L\'app ha due modalità. Ascolta è per la musica: Componi, Brani, Playlist, Radio. Groove Lab è per costruire e imparare: Artisti, Stili, Generi, Suoni, Pattern, Guida, Lezioni Strudel, Riferimenti.' },
    how: { en: 'Press [▶ Listen] or [⚗ Groove Lab] at the top, then a tab.', it: 'Premi [▶ Ascolta] o [⚗ Groove Lab] in alto, poi una scheda.' },
    know: { en: 'Each mode remembers its last tab. The live code on the right and the settings gear are there in both modes.', it: 'Ogni modalità ricorda la sua ultima scheda. Il codice dal vivo a destra e l\'ingranaggio delle impostazioni ci sono in tutte e due.' },
  },
  {
    id: 'player', tab: null, mode: null, show: '.pbar',
    title: { en: 'Player bar', it: 'Barra del player' },
    what: { en: 'The bar at the bottom plays whatever is on: a song, a playlist or the radio.', it: 'La barra in fondo suona quello che è acceso: un brano, una playlist o la radio.' },
    how: { en: 'Previous, play, stop, next; drag the timeline to move in the song. Shuffle, repeat (off, all, one) and Mix change how a playlist plays. Volume and mute on the right.', it: 'Precedente, play, stop, successivo; trascina la timeline per spostarti nel brano. Casuale, ripeti (spento, tutto, uno) e Mix cambiano come suona una playlist. Volume e muto a destra.' },
    know: { en: 'Next to the time, "bar 12 / 64" counts the bars of what plays (in Live coder and Crescendo the growth, then the written part); stopped in Compose it shows the bar Play starts from. Mix joins saved songs with transitions, like the radio. The volume does not change exported files.', it: 'Accanto al tempo, "bar 12 / 64" conta le battute di quello che suona (in Live coder e Crescendo la crescita, poi la parte scritta); da fermo in Componi mostra la battuta da cui parte Play. Mix unisce i brani salvati con le transizioni, come la radio. Il volume non cambia i file esportati.' },
  },
  {
    id: 'visuals', tab: null, mode: null, show: '#looks',
    title: { en: 'Visuals and the song soul', it: 'Visual e anima del brano' },
    what: { en: 'The stage at the top moves with the music. Soul shows the song playing as a retro science-fiction screen, drawn from its seed, settings, curves and instruments: every song looks different.', it: 'Il palco in alto si muove con la musica. Anima mostra il brano che suona come uno schermo di fantascienza retrò, disegnato dal suo seme, dalle impostazioni, dalle curve e dagli strumenti: ogni brano ha un aspetto diverso.' },
    how: { en: 'Pick a visual in the menu at the top right of the stage, or step through them with [◀] and [▶] beside it. The Render menu next to them draws any visual another way: Normal, 1-bit (two colours with a dot pattern), CRT (glow, grille and scanlines), LED (a dot matrix), ASCII (characters) or Terminal (a text interface with panels and a status bar); the code panel never changes. [Fullscreen] fills the screen. Soul is locked in the menu: it needs a signal. When the soul shows, [◀] and [▶] change the view (ten of them) and [lock] keeps the view when the song changes.', it: 'Scegli un visual nel menu in alto a destra del palco, o scorrili con [◀] e [▶] accanto. Il menu Render lì vicino disegna qualunque visual in un altro modo: Normale, 1-bit (due colori a puntini), CRT (bagliore, griglia e righe), LED (una matrice di punti), ASCII (caratteri) o Terminale (un\'interfaccia di testo con pannelli e barra di stato); il pannello del codice non cambia mai. [Schermo intero] riempie lo schermo. Anima nel menu è bloccata: serve un segnale. Quando l\'anima si vede, [◀] e [▶] cambiano vista (sono dieci) e [lucchetto] tiene la vista al cambio di brano.' },
    know: { en: 'Two visuals show what each instrument plays: Monitor gives every playing instrument a panel (up to six) with its widget, name and level, dimmed while it is silent; Roll draws the melodic parts on one piano roll in their colours, with kick, snare and hats as rows of dots below. Both take the instruments and widgets of the Code widgets card in Settings, change only at a new section and come out the same in videos. Claude shows the song as an agent at work in a terminal: what enters, what comes next, the instruments in panes and a line being typed. Videos and fragments use the stage\'s render unless their settings pick another; on a slow device the render can draw fewer cells or dots (Settings, Render on slow devices). Each song starts in its own view. A new song is analyzed first; a change from the radio console makes the screen glitch while it recalibrates. Soul keeps the colours of the last visual; in the HW theme the screens turn amber. There is something hidden in the stage, too…', it: 'Due visual mostrano cosa suona ogni strumento: Monitor dà a ogni strumento che suona un pannello (fino a sei) con il suo widget, il nome e il livello, attenuato mentre tace; Rullo disegna le parti melodiche su un solo rullo di pianola nei loro colori, con cassa, rullante e hats come file di punti sotto. Entrambi prendono strumenti e widget dalla card Widget nel codice delle Impostazioni, cambiano solo a una sezione nuova e escono uguali nei video. Claude mostra il brano come un agente al lavoro in un terminale: cosa entra, cosa viene dopo, gli strumenti nei riquadri e una riga che si scrive. Video e frammenti usano il render del palco, se le loro impostazioni non ne scelgono un altro; su un dispositivo lento il render può disegnare meno celle o punti (Impostazioni, Render su dispositivi lenti). Ogni brano parte nella sua vista. Un brano nuovo viene prima analizzato; un cambio dalla console della radio fa disturbare lo schermo mentre si ricalibra. Anima tiene i colori dell\'ultimo visual; nel tema HW gli schermi diventano ambra. E nel palco c\'è anche qualcosa di nascosto…' },
  },
  {
    id: 'compose', tab: 'componi', mode: 'ascolta', show: '#arranger',
    title: { en: 'Compose', it: 'Componi' },
    what: { en: 'The workbench of a song: tracks, sections and their settings. Every change writes the Strudel code on the right.', it: 'Il banco di lavoro di un brano: tracce, sezioni e le loro impostazioni. Ogni modifica scrive il codice Strudel a destra.' },
    how: { en: '[Open song] or [New song]; [+ Add track] and [+ Add section]; pick a section to set tempo, key, chords, meter and entry. [▶ Play from this section], [Loop section]. [Save] or [Save as new].', it: '[Apri brano] o [Nuovo brano]; [+ Aggiungi traccia] e [+ Aggiungi sezione]; scegli una sezione per tempo, tonalità, accordi, metro ed entrata. [▶ Suona da questa sezione], [Ripeti la sezione]. [Salva] o [Salva come nuovo].' },
    know: { en: '[Live build] plays the song as it builds up, one change per phrase. [▶ Continue in radio] plays the song on from where it is, then the radio goes on after it. {Ctrl}+{Enter} plays from anywhere, {Ctrl}+{.} stops. The code is short, as a live coder writes it: parts are ideas (a cell with its repetition like [~ x x x]*4, sequencer steps, degrees, chords with a voicing), presets included, and the song sounds the same. A pattern that holds an idea fills [Steps] from it and shows it as code under the row; editing the steps writes it out (the idea becomes steps).', it: '[In divenire] suona il brano mentre si costruisce, un cambio per frase. [▶ Continua in radio] suona il brano da dove sei, poi la radio continua dopo di lui. {Ctrl}+{Enter} suona da qualsiasi punto, {Ctrl}+{.} ferma. Il codice è corto, come lo scrive un live coder: le parti sono idee (una cella con la sua ripetizione come [~ x x x]*4, passi di sequencer, gradi, accordi con un voicing), preset compresi, e il brano suona uguale. Un pattern che contiene un\'idea riempie [Passi] da quella e la mostra come codice sotto la riga; modificare i passi la scrive per esteso (l\'idea diventa passi).' },
    parts: [{
      id: 'song-config', title: { en: 'The song\'s configuration', it: 'La configurazione del brano' },
      what: { en: 'Profile, Live build and their options belong to the song: a song plays with the configuration it was saved with, and a song without one plays as written (Classic, Live build off). Changing them in Compose is a trial on this song only. With the Live build off the panel keeps only the code options (comments, technical functions, title, lit notes, line breaks), under Code. ↺ Original song is active when the song itself changed, ↺ Original configuration when its configuration is a trial.', it: 'Profilo, In divenire e le loro opzioni fanno parte del brano: un brano suona con la configurazione con cui è stato salvato, e un brano senza configurazione suona com\'è scritto (Classico, In divenire spento). Cambiarle in Componi è una prova solo su questo brano. Con In divenire spento il pannello tiene solo le opzioni del codice (commenti, funzioni tecniche, titolo, note accese, a capo), sotto Codice. ↺ Brano originale è attivo quando è cambiato il brano, ↺ Configurazione originale quando la configurazione è una prova.' },
      how: { en: 'Change the profile or an option: the song shows "configuration changed". [↺ Original configuration] (in the song actions, and next to the mark on the song\'s card) undoes the trial. [Save] makes the trial the song\'s own configuration, [Save as new] makes a copy with it. On a built-in song [Save] makes your version, and [↺ Original song], next to it, brings back the built-in song as it was: notes, tracks and configuration. Each is greyed out when there is nothing to restore.', it: 'Cambia il profilo o un\'opzione: il brano mostra "configurazione cambiata". [↺ Configurazione originale] (nelle azioni del brano, e accanto al segno sulla card del brano) annulla la prova. [Salva] rende la prova la configurazione del brano, [Salva come nuovo] fa una copia con quella. Su un brano incluso [Salva] fa la tua versione, e [↺ Brano originale], accanto, riporta il brano incluso com\'era: note, tracce e configurazione. Ognuno è spento quando non c\'è niente da ripristinare.' },
      know: { en: 'A trial never reaches other songs or the saved song, survives a reload and goes into the backup. The song\'s card shows its length with the trial.', it: 'Una prova non tocca mai gli altri brani né il brano salvato, resta dopo un ricaricamento e va nel backup. La card del brano mostra la durata con la prova.' },
    }, {
      id: 'fm-like-effects', title: { en: 'FM-like effects in the rack', it: 'Effetti simili all\'FM nel rack' },
      what: { en: 'FM works only on synth oscillators. Two rack devices give an FM-like colour to any track, drums, samples and voices included: [Fold] folds the wave back on itself (bright, hollow, metallic), [Ring (trial)] multiplies the sound by a sine wave (bells, metal, robot voices).', it: 'L\'FM funziona solo sugli oscillatori dei synth. Due moduli del rack danno un colore simile all\'FM a qualsiasi traccia, batteria, campioni e voci compresi: [Piega] ripiega l\'onda su se stessa (brillante, cavo, metallico), [Ring (prova)] moltiplica il suono per un\'onda sinusoidale (campane, metallo, voci da robot).' },
      how: { en: 'In the track panel, under Rack, pick [Fold] or [Ring (trial)] and press [+ Add device]. Fold: [Amount] (how hard it folds) and [Curve] ([Sharp] or [Soft]). Ring: [Frequency (Hz)] and [Amount] (from the dry sound to the full ring).', it: 'Nel pannello della traccia, sotto Rack, scegli [Piega] o [Ring (prova)] e premi [+ Aggiungi modulo]. Piega: [Quantità] (quanto piega) e [Curva] ([Spigolosa] o [Morbida]). Ring: [Frequenza (Hz)] e [Quantità] (dal suono asciutto al ring pieno).' },
      know: { en: 'Fold folds only what is loud enough: drums, basses and voices from Amount 1.5, quiet pads from 2.5. A folded line never goes above its own peak or the usual peak of its track type. Fold uses the same stage as Distortion and the track\'s own drive (Saturation on drums, the guitar\'s distortion): it takes their place. Ring is a trial: it plays in the page and in the fast export, it never makes a line louder, and it turns a stereo sample into mono. Radio voices sometimes get a mild Fold.', it: 'Piega piega solo ciò che è abbastanza forte: batteria, bassi e voci da Quantità 1,5, i pad leggeri da 2,5. Una linea piegata non supera mai il suo picco né il picco abituale del suo tipo di traccia. Piega usa lo stesso stadio di Distorsione e della saturazione della traccia (Saturazione della batteria, distorsione della chitarra): prende il loro posto. Ring è una prova: suona nella pagina e nell\'export veloce, non alza mai il volume di una linea e rende mono un campione stereo. Le voci della radio a volte ricevono una Piega leggera.' },
    }, {
      id: 'compose-part', title: { en: 'Compose a part', it: 'Componi una parte' },
      what: { en: 'A new pattern for a drums, bass, arp, lead, pad or guitar track, composed from the song\'s key, chords, meter and style: short cells, a progression over the bars, chord indices, sequencer steps.', it: 'Un pattern nuovo per una traccia di batteria, basso, arpeggio, melodia, pad o chitarra, composto dalla tonalità, dagli accordi, dal metro e dallo stile del brano: celle brevi, una progressione sulle battute, indici negli accordi, passi di sequencer.' },
      how: { en: 'In the track panel, under Make: set [Energy] (more notes and a wider range, or sparse and narrow) and press [Compose a part]. The new pattern takes the next letter and is selected; press the headphones by the preset menu to preview it, or put it in a section with [Use D in «section»]. With a preset selected, [Keep rhythm] keeps its hits with new notes and [Keep notes] keeps its notes with a new rhythm. On a guitar track, [Guitar] chooses [Riff] (quick steps over the power chord) or [Chords] (power chords only); the choice stays while the page is open.', it: 'Nel pannello della traccia, sotto Crea: regola [Energia] (più note e un registro più ampio, o parti rade e strette) e premi [Componi una parte]. Il pattern nuovo prende la lettera dopo ed è selezionato; premi la cuffia accanto al menu dei preset per l\'anteprima, o mettilo in una sezione con [Usa D in «sezione»]. Con un preset selezionato, [Tieni il ritmo] tiene i suoi colpi con note nuove e [Tieni le note] tiene le sue note con un ritmo nuovo. Su una traccia di chitarra, [Chitarra] sceglie [Riff] (passi veloci sopra il power chord) o [Accordi] (solo power chord); la scelta resta finché la pagina è aperta.' },
      know: { en: 'The number next to the action makes the part: the same number gives the same part, each press moves to the next one, and typing a number composes that part again. The style is the song\'s first style tag, else the style closest to its tempo and meter. The patterns the track already had do not change. A composed melody says its shape (changed tail, call and response, polymeter) in the message and on its pattern until the page reloads.', it: 'Il numero accanto all\'azione fa la parte: lo stesso numero dà la stessa parte, ogni pressione passa al numero dopo, e scrivere un numero ricompone quella parte. Lo stile è il primo tag di stile del brano, altrimenti lo stile più vicino al suo tempo e al suo metro. I pattern che la traccia aveva non cambiano. Una melodia composta dice la sua forma (coda cambiata, botta e risposta, poliritmo) nel messaggio e sul suo pattern, finché la pagina non si ricarica.' },
    }, {
      id: 'pattern-preview', title: { en: 'Pattern preview', it: 'Anteprima del pattern' },
      what: { en: 'A small second player for the pattern selected in a track panel: it plays the pattern in a loop with the track\'s sound and level and the selected section\'s key, chords and tempo, and never takes over the player bar.', it: 'Un piccolo secondo player per il pattern scelto nel pannello di una traccia: suona il pattern in loop con il suono e il livello della traccia e la tonalità, gli accordi e il tempo della sezione scelta, e non prende mai la barra del player.' },
      how: { en: 'Press the headphones next to the Preset (or Groove) menu; press stop to end it. With the song playing it starts at the next bar and stays on the song\'s bars; with the song stopped it plays alone. The flask next to it opens the pattern in the Patterns tab. Patterns in this song holds the track\'s patterns, [+ New] and [Delete]; Make holds [Save as pattern] and [Compose a part].', it: 'Premi la cuffia accanto al menu Preset (o Groove); premi stop per finire. Con il brano che suona parte alla battuta dopo e resta sulle battute del brano; con il brano fermo suona da sola. La beuta accanto apre il pattern nella scheda Pattern. Pattern disponibili nel brano tiene i pattern della traccia, [+ Nuovo] ed [Elimina]; Crea tiene [Salva come pattern] e [Componi una parte].' },
      know: { en: 'The track keeps playing in the song: the M button mutes it to hear only the preview. An edit plays from the next bar. One preview at a time; it stops when you leave Compose, open another song, delete its pattern or export. The play triangle always means the player bar takes it; the headphones mean a preview.', it: 'La traccia continua a suonare nel brano: il pulsante M la mette in muto per sentire solo l\'anteprima. Una modifica suona dalla battuta dopo. Un\'anteprima alla volta; si ferma quando lasci Componi, apri un altro brano, elimini il suo pattern o esporti. Il triangolo di play vuol dire sempre che lo prende la barra del player; la cuffia vuol dire un\'anteprima.' },
    }, {
      id: 'pattern-row', title: { en: 'Patterns in this song', it: 'Pattern disponibili nel brano' },
      what: { en: 'One row in the track panel with the track\'s patterns: a chip chooses the pattern you edit and hear in the preview; the song changes only when you say so.', it: 'Una riga nel pannello della traccia con i pattern della traccia: un chip sceglie il pattern che modifichi e senti in anteprima; il brano cambia solo quando lo dici tu.' },
      how: { en: 'Choose a section in the arranger (or a clip in Free timeline), then a chip. The line under the row says what you edit and what the song plays there. [Use D in «section»] puts the pattern there. [Try on a copy] copies the pattern to the next letter, used nowhere, to change it apart; then [Replace B with D] puts the copy everywhere B played. [Restore B] brings B back to how it was when you chose it. [Nothing] silences the track in that section or removes the chosen clip. Each change offers [Undo] in the notice.', it: 'Scegli una sezione nell\'arrangiamento (o un clip nella timeline libera), poi un chip. La riga sotto dice cosa modifichi e cosa suona lì il brano. [Usa D in «sezione»] mette lì il pattern. [Prova su una copia] copia il pattern nella lettera dopo, non usato, per cambiarlo a parte; poi [Sostituisci B con D] mette la copia dovunque suonava B. [Ripristina B] riporta B com\'era quando l\'hai scelto. [Niente] fa tacere la traccia in quella sezione o toglie il clip scelto. Ogni cambio offre [Annulla] nell\'avviso.' },
      know: { en: 'Marks: IN THE SONG on the pattern of the chosen section or clip, a hollow circle on patterns used elsewhere, no mark on patterns used nowhere (only those can be deleted), the headphones on the pattern in preview, a pink border on the one you edit. Editing stays live: a change is heard wherever the pattern is used, from the next bar. With no section or clip chosen there is no badge and the row says how to choose one.', it: 'Segni: NEL BRANO sul pattern della sezione o del clip scelto, un cerchio vuoto sui pattern usati altrove, nessun segno sui pattern non usati (solo quelli si possono eliminare), la cuffia sul pattern in anteprima, un bordo rosa su quello che modifichi. La modifica è dal vivo: un cambio si sente dove il pattern è usato, dalla battuta dopo. Senza sezione o clip scelti non c\'è il badge e la riga dice come sceglierne uno.' },
    }, {
      id: 'growth-timeline', title: { en: 'The growth in the timeline', it: 'La crescita nella timeline' },
      what: { en: 'A song that grows (Live coder, Crescendo) plays its growth before the written sections, and sometimes an added ending after them. The ruler, the sections and the tracks show them as hatched, read-only columns: Growth before the first section (Waypoints for a song that starts with its waypoints without a live build), the ending after the last one. Each track shows where it plays in the growth, with a tick at each of its steps. A song that builds live without a narrator track has a last, dashed row, Narrator: it is not a track yet, it shows where the narrator speaks with the default sound (a count per section, a tick or a round mark per line), and it becomes the Narrator track the first time you change the narrator\'s sound.', it: 'Un brano che cresce (Live coder, Crescendo) suona la sua crescita prima delle sezioni scritte, e a volte un finale aggiunto dopo. Il righello, le sezioni e le tracce le mostrano come colonne tratteggiate in sola lettura: Crescita prima della prima sezione (Tappe per un brano che comincia con le sue tappe senza live build), il finale dopo l\'ultima. Ogni traccia mostra dove suona nella crescita, con una tacca a ogni suo passo. Un brano in divenire senza traccia del narratore ha un\'ultima riga tratteggiata, Narrator: non è ancora una traccia, mostra dove parla il narratore con il suono predefinito (quante frasi per sezione, una tacca o un pallino per frase) e diventa la traccia Narrator la prima volta che ne cambi il suono.' },
      how: { en: 'The eye next to Sections switches the growth: half-open is compact (a fixed width), open shows it at the same scale as the song (the arranger scrolls sideways), closed leaves a narrow tab. Click the ruler or drag the knob anywhere in the song, growth included; click Growth to start from bar 0, a section to go to it, a track\'s growth cell to go to its nearest step and select the track. On the Narrator row a cell or a mark goes to the narrator\'s nearest line (a section: its first line) without selecting a track; its name opens the Sound of Voice: narrator. On the ruler: arrows move one bar, {PgUp} and {PgDn} the previous or next step or section, {Home} the start, {End} the last bar, ending included.', it: 'L\'occhio accanto a Sezioni cambia la crescita: socchiuso è compatta (larghezza fissa), aperto la mostra alla stessa scala del brano (l\'arrangiamento scorre di lato), chiuso lascia una linguetta stretta. Clicca il righello o trascina il cursore in qualsiasi punto del brano, crescita compresa; clicca Crescita per partire dalla battuta 0, una sezione per andarci, la cella della crescita di una traccia per andare al suo passo più vicino e scegliere la traccia. Sulla riga Narrator una cella o un pallino va alla frase del narratore più vicina (una sezione: alla sua prima frase) senza scegliere una traccia; il nome apre il Suono di Voce: narratore. Sul righello: le frecce spostano di una battuta, {PagSu} e {PagGiù} al passo o alla sezione prima o dopo, {Home} all\'inizio, {Fine} all\'ultima battuta, finale compreso.' },
      know: { en: 'The knob, the time, the bar counter and the player bar count the same bars: the song as it plays. The eye is remembered in this browser. A song without growth looks as before. The Narrator row counts the lines you hear, as the code says them: a poetic image instead of the step line, nothing where the voice track speaks or the line has no sample. With the narrator off it stays, dimmed; with the Live build off it is not there; Undo of the first sound edit brings it back. While the song plays with Follow playback on, an arranger wider than the screen scrolls a page at a time to keep the knob in sight; scroll it yourself and it waits 3 seconds, or until you play or seek again.', it: 'Il cursore, il tempo, il contatore delle battute e la barra del player contano le stesse battute: il brano come suona. L\'occhio resta com\'è in questo browser. Un brano senza crescita resta come prima. La riga Narrator conta le frasi che senti, come le dice il codice: un\'immagine poetica al posto della frase del passo, niente dove parla la voce traccia o la frase non ha il campione. Con il narratore spento resta, attenuata; con In divenire spento non c\'è; Annulla della prima modifica del suono la fa tornare. Mentre il brano suona con Segui la riproduzione attivo, un arrangiamento più largo dello schermo scorre una pagina alla volta per tenere in vista il cursore; se lo scorri tu aspetta 3 secondi, o finché non premi di nuovo Play o ti sposti nel brano.' },
    }],
  },
  {
    id: 'new-song', tab: 'componi', mode: 'ascolta', show: '#tr-new',
    title: { en: 'New song', it: 'Nuovo brano' },
    what: { en: 'One place to start a new song: from scratch, written by the director with your choices (styles, knobs, artist, profile and growth, voices, material, length), or fully at random.', it: 'Un solo posto per iniziare un brano nuovo: da zero, scritto dal regista con le tue scelte (stili, manopole, artista, profilo e crescita, voci, materiale, durata), oppure tutto a caso.' },
    how: { en: '[New song] opens the panel under the title row ([×] or {Esc} closes it). [From scratch] makes the empty song with one drum track. Pick an [Artist] or a [Preset] and press [Generate]; [Surprise me] draws every choice from a new seed and generates. The sections [Style and genre], [Profile and growth], [Voices], [Material] and [Length] are folded, each with its values in one line. [Take from the radio] copies the radio\'s choices; the save and bin buttons next to [Preset] save your choices as a preset of yours or delete one.', it: '[Nuovo brano] apre il pannello sotto la riga del titolo ([×] o {Esc} lo chiude). [Da zero] crea il brano vuoto con una traccia di batteria. Scegli un [Artista] o un [Preset] e premi [Genera]; [Sorprendimi] tira ogni scelta da un seme nuovo e genera. Le sezioni [Stile e genere], [Profilo e crescita], [Voci], [Materiale] e [Durata] sono chiuse, ognuna con i suoi valori in una riga. [Prendi dalla radio] copia le scelte della radio; i tasti salva e cestino accanto a [Preset] salvano le tue scelte come preset tuo o ne eliminano uno.' },
    know: { en: 'The panel has the radio\'s controls with values of its own: a try here never changes the radio. The song opens unsaved with the chosen profile as its own configuration; the seed field shows the seed used, and the same seed with the same choices gives the same song. [Length] is the length you hear, growth included: with Crescendo or Live coder the growth fits in it, with Classic the song lasts about a phrase less. The song keeps that length when you switch its profile in Compose; [Free] growth turns it off, and a line says so. The die with a spark ([Invent]) puts an invented style on trial here, apart from the radio: [Generate] writes the song from it, [Keep] saves it among your styles.', it: 'Il pannello ha i controlli della radio con valori suoi: una prova qui non cambia mai la radio. Il brano si apre non salvato con il profilo scelto come configurazione sua; il campo seme mostra il seme usato, e lo stesso seme con le stesse scelte dà lo stesso brano. [Durata] è la durata che senti, crescita compresa: con Crescendo o Live coder la crescita ci sta dentro, con Classico il brano dura circa una frase in meno. Il brano tiene quella durata quando cambi profilo in Componi; la crescita [Libera] la toglie, e una riga lo dice. Il dado con la scintilla ([Inventa]) mette qui uno stile inventato in prova, separato dalla radio: [Genera] scrive il brano con quello, [Tieni] lo salva tra i tuoi stili.' },
  },
  {
    id: 'crescendo', tab: 'componi', mode: 'ascolta', show: '#live-style',
    title: { en: 'Crescendo', it: 'Crescendo' },
    what: { en: 'A build style of the live build: the song starts from one sound and grows in small steps, a line or two at a time, like a live coder, until it sounds as written.', it: 'Un andamento del brano in divenire: il brano parte da un suono solo e cresce a piccoli passi, una riga o due alla volta, come un live coder, finché suona come è scritto.' },
    how: { en: 'Turn on [Live build], set [Build style] to crescendo and play. [Narrated growth] (in the [Voices] group) makes the steps denser, each one spoken. The [On] switch of [Voice: narrator] in the Voices group switches the voice that speaks the step phrases off, and the phrase over the stage with it: the music and the length stay the same, the phrases in the code follow the comment options, and [Narrated growth] is disabled until the narrator voice is on again. The code menu shows compact code (identical lines joined, tracks still to come muted), one line per track, or code per section; the sound is the same.', it: 'Accendi [In divenire], metti [Andamento] su crescendo e suona. [Crescita raccontata] (nel gruppo [Voci]) rende i passi più fitti e li fa dire tutti. L\'interruttore [Accesa] di [Voce: narratore] nel gruppo Voci spegne la voce che dice le frasi dei passi, e con lei la frase sopra il palco: la musica e la durata restano le stesse, le frasi nel codice seguono le opzioni dei commenti, e [Crescita raccontata] resta disattivata finché la voce narratore non torna accesa. Il menu del codice mostra il codice compatto (righe uguali unite, tracce ancora da entrare spente), una riga per traccia, o il codice per sezione; il suono è lo stesso.' },
    know: { en: 'The growth plays the first full section over and over before the song as written, first over one held chord. A song can declare its build style or its whole configuration and opens with it. The same song always grows the same way. The code types itself like a person: a new line like one above is pasted and then changed, and with [Line breaks] (on in the Live coder profile) a line wider than the panel breaks before a function. [Technical functions] is a preset over options, like the comments: full, short (.chan("bass"), .crunch(0.6)), mixer (bus, visual and level hidden) or compact (on in Live coder), where effect chains that repeat become functions: the library (.plk(), .wet(), .res(), .wob()) and functions of the song with a themed name, values that change in the brackets; sounds, notes and rhythms stay written; [Sections] (in compact) takes the section and clip lanes out of the code into the hidden mixer: each part is one line, changed in place when its section or clip changes, in every profile and also for a song played as written with the Live build off; in code changed in place, a line that pauses and comes back later stays muted with _$: and is switched on again where it was; in Live coder a new line may appear muted a few steps before it plays, typed at a quiet step of the growth or of the song, and its step only switches it on; [Hidden code] under the panel shows what plays with the code, and Copy includes it. The comment options hide track names, notes, phrases or the narrator voice code (the narrator still speaks); the Live coder shows only the title. [Human typing] (on in Live coder) types like a person: a listening pause, an uneven pace, pauses to think, sometimes a long line pasted whole. [Typing mistakes] (on with it) leaves a wrong key on screen for a moment before fixing it, sometimes types a whole wrong word or changes a number; some stretches are careful, others hurried. [Growth]: small steps, gradual, or natural like a live coder (4 to 6 small waypoints drawn at the start, small moves between them, lines copied and changed, something taken out and put back); its duration is free or at most as long as the written song. A song can start with its waypoints when it plays without a live build. In the Live coder profile a part that is an idea grows from its simple form (one note per beat, the chord held, the first degree) to the written one; Classic and Crescendo thin the written steps as before. A step can switch on a prepared variant: its line loses the //.', it: 'La crescita ripete la prima sezione piena prima del brano scritto, all\'inizio su un solo accordo. Un brano può dichiarare il suo andamento o tutta la sua configurazione e si apre con quella. Lo stesso brano cresce sempre allo stesso modo. Il codice si scrive come lo scriverebbe una persona: una riga nuova simile a una sopra viene incollata e poi cambiata, e con [A capo] (acceso nel profilo Live coder) una riga più larga del pannello va a capo prima di una funzione. [Funzioni tecniche] è un preset sopra delle opzioni, come i commenti: per esteso, abbreviate (.chan("bass"), .crunch(0.6)), al mixer (bus, visual e volume nascosti) o compatte (acceso in Live coder), dove le catene di effetti che si ripetono diventano funzioni: la libreria (.plk(), .wet(), .res(), .wob()) e funzioni del brano con un nome a tema, i valori che cambiano tra parentesi; suoni, note e ritmi restano scritti; [Sezioni] (in compatte) porta le corsie delle sezioni e dei clip dal codice al mixer nascosto: ogni parte è una riga, cambiata sul posto quando cambia la sua sezione o il suo clip, in ogni profilo e anche per un brano suonato com\'è scritto con In divenire spento; nel codice cambiato sul posto, una riga che tace e torna più avanti resta spenta con _$: e viene riaccesa dov\'era; in Live coder una riga nuova può comparire spenta qualche passo prima di suonare, scritta in un passo tranquillo della crescita o del brano, e il suo passo la accende soltanto; [Codice nascosto] sotto il pannello mostra cosa suona insieme al codice, e Copia lo include. Le opzioni dei commenti nascondono nomi delle tracce, note, frasi o il codice voce narratore (il narratore parla lo stesso); il Live coder mostra solo il titolo. [Scrittura umana] (accesa in Live coder) scrive come una persona: una pausa di ascolto, velocità irregolare, pause per pensare, a volte una riga lunga incollata intera. [Errori di battitura] (acceso insieme) lascia un tasto sbagliato sullo schermo per un attimo prima di correggerlo, a volte scrive una parola intera sbagliata o cambia un numero; alcuni tratti sono attenti, altri di fretta. [Crescita]: a piccoli passi, graduale, o naturale come un live coder (da 4 a 6 tappe piccole decise all\'inizio, mosse piccole tra una e l\'altra, righe copiate e cambiate, qualcosa tolto e rimesso); la sua durata è libera o al massimo quanto il brano scritto. Un brano può cominciare con le sue tappe quando suona senza live build. Nel profilo Live coder una parte che è un\'idea cresce dalla sua forma semplice (una nota per beat, l\'accordo tenuto, il primo grado) a quella scritta; Classico e Crescendo sfoltiscono i passi scritti come prima. Un passo può accendere una variante pronta: la sua riga perde il //.' },
  },
  {
    id: 'growth-shapes', tab: 'componi', mode: 'ascolta', show: '#live-shape',
    title: { en: 'Growth shape', it: 'Forma della crescita' },
    what: { en: 'How a song grows in the Live coder profile: an opening, a pace and a development. Songs no longer all start from one kick: some open with the full kick, a broken beat, a filtered kick, an arpeggio, a pad, silence while the first line is typed, a written base kept muted, or two tracks already playing in solo.', it: 'Come cresce un brano nel profilo Live coder: un\'apertura, una velocità e uno sviluppo. I brani non partono più tutti da una cassa sola: alcuni si aprono con la cassa intera, un ritmo spezzato, una cassa filtrata, un arpeggio, un pad, il silenzio mentre si scrive la prima riga, una base scritta e muta, o due tracce che suonano già in solo.' },
    how: { en: 'In the live build options, with the growth natural (Live coder), [Opening], [Pace] and [Development] are each auto or one value; auto shows what the song draws, and the line above shows the shape that plays. A value set here makes the profile custom. Values the song cannot play are greyed out.', it: 'Nelle opzioni del brano in divenire, con la crescita naturale (Live coder), [Apertura], [Velocità] e [Sviluppo] sono ognuna auto o un valore; auto mostra cosa sceglie il brano, e la riga sopra mostra la forma che suona. Un valore scelto qui rende il profilo personalizzato. I valori che il brano non può suonare sono spenti.' },
    know: { en: 'Each part comes from your choice, else the song (growthShape), else the weights of its style, else the song\'s seed: the same song always has the same shape. Pace: slow as before, medium a step every 10 to 15 seconds, fast about every 8 seconds with small moves; with medium and fast the kick is whole within the first minute. The typing never rushes: a step that takes long to type comes later, or joins the edit before it on the same line. Development: by type, as written, masks (each instrument comes in, leaves and varies), parameters only, a second section built alone with S$: and then joined, or a metamorphosis (tempo, key and the parts of another style of the same family, one line at a time). Moves: a beat step moved, a prepared variant uncommented, seg(16) on a held chord, a value that slides; a melody may pass by and leave, always the song\'s own part. Classic and Crescendo do not use shapes. The voice track opening waits for the voice track.', it: 'Ogni parte viene dalla tua scelta, altrimenti dal brano (growthShape), altrimenti dai pesi del suo stile, altrimenti dal seme del brano: lo stesso brano ha sempre la stessa forma. Velocità: lenta come prima, media un passo ogni 10-15 secondi, veloce circa ogni 8 secondi con mosse piccole; con media e veloce la cassa è intera entro il primo minuto. La scrittura non corre mai: un passo lungo da scrivere arriva più tardi, o si unisce alla modifica prima sulla stessa riga. Sviluppo: per tipo, come scritto, maschere (ogni strumento entra, esce e varia), solo parametri, una seconda sezione costruita da sola con S$: e poi unita, o una metamorfosi (tempo, tonalità e le parti di un altro stile della stessa famiglia, una riga alla volta). Mosse: un colpo del ritmo spostato, una variante pronta scommentata, seg(16) su un accordo tenuto, un valore che scivola; una melodia può passare e andarsene, sempre una parte del brano. Classico e Crescendo non usano le forme. L\'apertura voce traccia aspetta la voce traccia.' },
  },
  {
    id: 'growing', tab: 'componi', mode: 'ascolta', show: '#live-profile',
    title: { en: 'A song that grows', it: 'Un brano che cresce' },
    what: { en: 'Crescendo and Live coder grow the song before it plays: the steps, the shape and the typing are worked out for the whole song. A Live coder growth can take a few seconds on a long song, so it runs in the background and the page keeps answering.', it: 'Crescendo e Live coder fanno crescere il brano prima che suoni: i passi, la forma e la scrittura si calcolano per tutto il brano. Una crescita Live coder può richiedere qualche secondo su un brano lungo, per questo avviene in sottofondo e la pagina continua a rispondere.' },
    how: { en: 'Pick a profile, a build style, a growth, a duration, an opening, a pace, a development or [Narrated growth]: the choice shows at once. While the song grows, a small turning mark sits next to the profiles; the song stays as written until it is grown. Press [Play] meanwhile and the same mark shows on Play: the grown song starts from its first bar as soon as it is ready. Export waits the same way.', it: 'Scegli un profilo, un andamento, una crescita, una durata, un\'apertura, una velocità, uno sviluppo o [Crescita raccontata]: la scelta si vede subito. Mentre il brano cresce, un piccolo segno che gira sta accanto ai profili; il brano resta com\'è scritto finché non è cresciuto. Se premi [Play] nel frattempo, lo stesso segno compare su Play: il brano cresciuto parte dalla prima battuta appena è pronto. L\'esportazione aspetta allo stesso modo.' },
    know: { en: 'A newer choice drops the growth still running and grows only the last one. The growths made here are kept in this browser (up to 60, the least used dropped first), so after a reload the song opens grown at once; an update of the app that changes the growth clears them. They are not part of the backup. If a growth fails, the song plays as written and a message says so.', it: 'Una scelta più recente lascia perdere la crescita ancora in corso e fa crescere solo l\'ultima. Le crescite fatte qui restano in questo browser (fino a 60, quelle usate meno di recente escono per prime), così dopo un ricaricamento il brano si apre già cresciuto; un aggiornamento dell\'app che cambia la crescita le cancella. Non fanno parte del backup. Se una crescita non riesce, il brano suona come è scritto e un messaggio lo dice.' },
  },
  {
    id: 'voice-instrument', tab: 'componi', mode: 'ascolta', show: '#tk-type',
    title: { en: 'Voice: track', it: 'Voce: traccia' },
    what: { en: 'A voice that is part of the music, apart from the narrator. The narrator explains the steps of a live build; the voice track plays in the song as written, in exports and in every live build, in four ways: a spoken opening, a refrain repeated in the parts where it may speak, a chopped word played in rhythm, and a spoken passage.', it: 'Una voce che fa parte della musica, diversa dal narratore. Il narratore spiega i passi del brano in divenire; la voce traccia suona nel brano così com\'è scritto, negli export e in ogni brano in divenire, in quattro modi: un\'apertura parlata, un ritornello ripetuto nelle parti dove può parlare, una parola tagliata e suonata a ritmo, e un passaggio parlato.' },
    how: { en: 'Add a track of type [Voice: track] (or [Add Voice: track] in the Voices group), then open [Phrases] in its block: every line with its bars, way and text, editable in place. [Fill with] gives each row a line of a vocabulary (Dark, Calm, Machine, Night), [+ Add line] adds one in the next free part where it may speak, the bin removes one; Undo in the message puts it back. [Where it speaks] picks quiet, medium and busy parts (quiet first). In the radio, [How often] is As the style says, Often or Always (every next song gets one), and the [On] switch takes it away. Run npm run voices once to make the samples; on the dev server a line written here gets its sample by itself.', it: 'Aggiungi una traccia di tipo [Voce: traccia] (o [Aggiungi Voce: traccia] nel gruppo Voci), poi apri [Frasi] nel suo blocco: ogni frase con le sue battute, il modo e il testo, da cambiare sul posto. [Riempi con] dà a ogni riga una frase di un vocabolario (Scuro, Calmo, Macchina, Notte), [+ Aggiungi frase] ne aggiunge una nella prossima parte libera dove può parlare, il cestino ne toglie una; Annulla nel messaggio la rimette. [Dove parla] sceglie parti tranquille, medie e piene (prima le tranquille). In radio [Quanto spesso] è Come dice lo stile, Spesso o Sempre (ogni brano dopo ne ha una), e l\'interruttore [Accesa] la toglie. Lancia una volta npm run voices per creare i campioni; con il server di sviluppo una frase scritta qui si fa il campione da sola.' },
    know: { en: 'In Crescendo and Live coder the bars shown are the ones you hear, with the written bar next to them; a bar typed there is stored as written, a bar inside the growth is refused. When the narrator and the voice track would speak on the same bar, the narrator is quiet. With [Voice: narrator] off the voice track still speaks. Every style has a chance of a voice track (country none). Without samples on this computer the lines stay silent and their row says so; songs still play. Sung vocals are not part of it.', it: 'In Crescendo e Live coder le battute mostrate sono quelle che si sentono, con accanto quella scritta; una battuta scritta lì si salva come scritta, una battuta dentro la crescita viene rifiutata. Quando narratore e voce traccia parlerebbero sulla stessa battuta, il narratore tace. Con [Voce: narratore] spenta la voce traccia parla ancora. Ogni stile ha una probabilità di voce traccia (country nessuna). Senza campioni su questo computer le frasi restano mute e la loro riga lo dice; i brani suonano comunque. La voce cantata non ne fa parte.' },
  },
  {
    id: 'voices', tab: 'componi', mode: 'ascolta', show: '#live-voices',
    title: { en: 'Two voices', it: 'Due voci' },
    what: { en: 'The app has two voices. Voice: narrator explains the steps of a live build ("need bass"); its poetic style is the same voice with a short image before each track comes in. Voice: track is part of the song: short lines spoken in its parts, also in the song as written and in exports.', it: 'L\'app ha due voci. Voce: narratore spiega i passi del brano in divenire ("serve il basso"); il suo stile poetico è la stessa voce con una breve immagine prima che entri ogni traccia. Voce: traccia fa parte del brano: brevi frasi dette nelle sue parti, anche nel brano così com\'è scritto e negli export.' },
    how: { en: 'The [Voices] group in Compose has a block per voice, each with its [On] switch in the title row (off greys the block and keeps every value; for the voice track it is the track\'s mute). [Voice: narrator]: [Narrator style], [Narrated growth], the folded [Sound] and the [Narrator lines] of the build that plays. [Voice: track]: the presets, [New phrases], the folded [Phrases] (the list, [Fill with], [+ Add line], [Where it speaks]) and [Sound]. [Sound] has the [Voice style] (Clear, Radio, Distant, Robot, Deep, Bright, Cathedral, Echo, Dirty, Slow: it never changes the speaker or the volume), the speaker and eight controls: the same values as the track panel, so a change shows in both at once. A song with no narrator track gets one, named Narrator, on the first edit, with Undo; until then the timeline shows it as a dashed Narrator row. With the Live build off the narrator block says the song has no narrator, and its Sound and Narrator lines fold; they open again as you left them when you turn the Live build on. In the radio the [Voices] group holds the same two blocks for the next songs; the song on air changes from the console\'s Voice group. In the hardware theme the Sound controls are faders.', it: 'Il gruppo [Voci] in Componi ha un blocco per voce, ognuno con il suo interruttore [Accesa] nella riga del titolo (spenta, il blocco diventa grigio e tiene ogni valore; per la voce traccia è il muto della traccia). [Voce: narratore]: [Stile del narratore], [Crescita raccontata], il [Suono] chiuso e le [Frasi del narratore] della versione che suona. [Voce: traccia]: i preset, [Nuove frasi], le [Frasi] chiuse (l\'elenco, [Riempi con], [+ Aggiungi frase], [Dove parla]) e il [Suono]. Il [Suono] ha lo [Stile della voce] (Chiara, Radio, Lontana, Robot, Profonda, Luminosa, Cattedrale, Eco, Sporca, Lenta: non cambia mai chi parla né il volume), la voce che parla e otto controlli: gli stessi valori del pannello della traccia, così una modifica si vede subito in tutti e due. Un brano senza traccia del narratore ne riceve una, chiamata Narrator, alla prima modifica, con Annulla; fino ad allora la timeline la mostra come una riga Narrator tratteggiata. Con In divenire spento il blocco del narratore dice che il brano non ha il narratore, e il Suono e le Frasi del narratore si chiudono; si riaprono come li avevi lasciati quando accendi In divenire. In radio il gruppo [Voci] ha gli stessi due blocchi per i prossimi brani; il brano in onda si cambia dal gruppo Voce della console. Nel tema hardware i controlli del Suono sono fader.' },
    know: { en: 'When two would speak on the same bar the narrator is quiet. With the poetic style and Narrated growth the narrator says an image before each track comes in and a short image of movement at the other steps ("the light shifts"); the step that brings a track in keeps its line, an image wins a shared bar, and the stage always shows the step line. The radio knob and curve [Voice: narrator] (once Narrator) set how often the narrator comments the changes; they do not touch the voice track. Lines go to the parts Where it speaks allows (quiet ones first), never two in one part, so the number of lines is a ceiling. The console\'s [Add a line] needs the voice helper of the dev server (macOS): it makes the sample, then the line is said on the first bar after (Say now) or in the next free part (At the right moment), recorded so Replay says it again.', it: 'Quando due parlerebbero sulla stessa battuta il narratore tace. Con lo stile poetico e Crescita raccontata il narratore dice un\'immagine prima che entri ogni traccia e una breve immagine di movimento negli altri passi ("la luce si sposta"); il passo che fa entrare una traccia tiene la sua frase, su una battuta in comune vince l\'immagine, e il palco mostra sempre la frase del passo. La manopola e la curva [Voce: narratore] della radio (prima Narratore) dicono quanto spesso il narratore commenta i cambi; non toccano la voce traccia. Le frasi vanno nelle parti che Dove parla permette (prima le tranquille), mai due nella stessa parte, quindi il numero di frasi è un massimo. [Aggiungi frase] della console ha bisogno dell\'aiutante voce del server di sviluppo (macOS): fa il campione, poi la frase si dice alla prima battuta dopo (Dilla ora) o nella prossima parte libera (Al momento giusto), registrata così il Replay la ridice.' },
  },
  {
    id: 'hand', tab: 'componi', mode: 'ascolta', show: '#edhost',
    title: { en: 'Code by hand', it: 'Codice a mano' },
    what: { en: 'You can write in the live code while a song or the radio plays: your code takes over.', it: 'Puoi scrivere nel codice dal vivo mentre suona un brano o la radio: il tuo codice prende il controllo.' },
    how: { en: 'Type in the code and press {Ctrl}+{Enter}. [Resume live build] goes back to the song, with [from where I was] to restart at the bar where you began. [Save as new version] keeps your code as a version of the song.', it: 'Scrivi nel codice e premi {Ctrl}+{Enter}. [Riprendi il divenire] torna al brano, con [dal punto in cui ero] per ripartire dalla battuta in cui hai iniziato. [Salva come nuova versione] tiene il tuo codice come versione del brano.' },
    know: { en: 'Versions show on the original song\'s card. Touching a control of the composition writes the code again.', it: 'Le versioni compaiono sulla card del brano originale. Toccare un controllo della composizione riscrive il codice.' },
  },
  {
    id: 'songs', tab: 'brani', mode: 'ascolta', show: '#sv-q',
    title: { en: 'Songs', it: 'Brani' },
    what: { en: 'Every song: the app\'s, yours and those saved from the radio, with search, tags and favourites.', it: 'Tutti i brani: quelli dell\'app, i tuoi e quelli salvati dalla radio, con ricerca, tag e preferiti.' },
    how: { en: 'Type in the search (it understands both languages: "frigio" finds "phrygian"), tap a genre, style or kind chip, sort. ☆ adds to the favourites, [+ Playlist] adds to a playlist, [▶ Continue in radio] lets the radio go on after the song. The playlist menu on top plays one.', it: 'Scrivi nella ricerca (capisce tutte e due le lingue: "frigio" trova "phrygian"), tocca un chip di genere, stile o tipo, ordina. ☆ mette tra i preferiti, [+ Playlist] aggiunge a una playlist, [▶ Continua in radio] fa continuare la radio dopo il brano. Il menu delle playlist in alto ne suona una.' },
    know: { en: 'The list shows 20 songs a page; search, filters and order work on every song. Sort by recently created or recently played, filter never played songs or a build style. A tap on a tag of a card filters by it; the legend explains the tag colours. Your songs can have their own tags. [⬇ Export] saves the song as audio or as a video: the small display next to it switches (AUDIO or VIDEO). Audio is ready in a few seconds (WAV, FLAC, MP3 or Opus, with a .timeline.json); a video too renders faster than real time, directed by Settings → Video (layout, visual, soul, presets).', it: 'L\'elenco mostra 20 brani per pagina; ricerca, filtri e ordine valgono su tutti i brani. Ordina per creati o ascoltati di recente, filtra i mai ascoltati o un andamento. Un tocco su un tag di una card filtra per quel tag; la legenda spiega i colori. I tuoi brani possono avere tag tuoi. [⬇ Esporta] salva il brano in audio o in video: il piccolo display accanto cambia (AUDIO o VIDEO). L\'audio è pronto in pochi secondi (WAV, FLAC, MP3 o Opus, con un .timeline.json); anche il video si genera più veloce del tempo reale, con la regia di Impostazioni → Video (layout, visual, anima, preset).' },
    parts: [{
      id: 'songs-trash', title: { en: 'Delete, trash and test songs', it: 'Eliminare, cestino e brani di test' },
      what: { en: 'Every song can be deleted: yours and your code versions wait in the trash 30 days before they go for good; the app\'s songs are hidden in this browser. The Test chip shows only test songs.', it: 'Ogni brano si può eliminare: i tuoi e le tue versioni in codice restano nel cestino 30 giorni prima di sparire per sempre; i brani inclusi nell\'app vengono nascosti in questo browser. Il chip Test mostra solo i brani di test.' },
      how: { en: 'The trash can in the bottom right corner of a card asks inside the card: [Delete] moves the song to the trash, [Cancel] or Esc keeps it. [Restore] in the message that follows undoes it. [Trash (n)] next to the playlist menu opens the trash: [Restore], [Delete for good], [Empty trash]. In Compose, [Delete song] asks the same under its buttons. Give a song the tag "test" ([Tags]) and the Test chip in Kind shows it; a tap on #test turns the chip on.', it: 'Il cestino in basso a destra di una card chiede conferma dentro la card: [Elimina] sposta il brano nel cestino, [Annulla] o Esc lo lascia dov\'è. [Ripristina] nel messaggio che segue annulla l\'eliminazione. [Cestino (n)] accanto al menu delle playlist apre il cestino: [Ripristina], [Elimina per sempre], [Svuota il cestino]. In Componi, [Elimina brano] chiede la stessa conferma sotto i pulsanti. Dai a un brano il tag "test" ([Tag]) e il chip Test in Tipo lo mostra; un tocco su #test accende il chip.' },
      know: { en: 'A deleted app song is hidden in this browser (the app\'s files do not change): it waits in the trash like yours, [Restore] shows it again, and after [Delete for good] or 30 days Settings → Library → [Show hidden built-in songs (n)] brings back every hidden one. An edited app song still offers [Restore original]. A deleted song leaves every playlist, favourites included, and restoring it does not put it back. Songs 30 days in the trash are deleted for good when the app starts or the trash opens. The trash and the hidden songs are part of the settings backup; importing a backup never deletes a song, and a song hidden on either side stays hidden.', it: 'Un brano incluso eliminato viene nascosto in questo browser (i file dell\'app non cambiano): resta nel cestino come i tuoi, [Ripristina] lo rimostra, e dopo [Elimina per sempre] o 30 giorni Impostazioni → Libreria → [Mostra i brani inclusi nascosti (n)] li rimette tutti. Un brano incluso che hai modificato offre ancora [Ripristina originale]. Un brano eliminato esce da tutte le playlist, preferiti compresi, e ripristinarlo non ce lo rimette. I brani nel cestino da 30 giorni vengono eliminati per sempre all\'avvio dell\'app o quando apri il cestino. Il cestino e i brani nascosti fanno parte del backup delle impostazioni; importare un backup non elimina mai un brano, e un brano nascosto da una delle due parti resta nascosto.' },
    }],
  },
  {
    id: 'playlists', tab: 'playlist', mode: 'ascolta', show: '#tab-playlist',
    title: { en: 'Playlists', it: 'Playlist' },
    what: { en: 'Lists of songs to play in a row. Favourites is the first list and fills up with the star.', it: 'Liste di brani da suonare di fila. Preferiti è la prima lista e si riempie con la stella.' },
    how: { en: '[New playlist] here, or [+ Playlist] on any song. Reorder by dragging or with the arrows, rename, delete. Play it: it moves to the next song by itself.', it: '[Nuova playlist] qui, o [+ Playlist] su un brano. Riordina trascinando o con le frecce, rinomina, elimina. Suonala: passa da sola al brano dopo.' },
    know: { en: 'A playlist can hold radio sessions (📻): they play as you heard them, then the list moves on. After a director update a session may sound different; ❄ Freeze keeps its songs as they are. ⬇ on a session exports it as one file, audio or video as the Export display says. Export and import a playlist as JSON, your songs and sessions included. Shuffle, repeat and Mix are in the player bar.', it: 'Una playlist può contenere sessioni della radio (📻): suonano come le hai sentite, poi la lista va avanti. Dopo un aggiornamento del regista una sessione può suonare diversa; ❄ Congela tiene i suoi brani così come sono. ⬇ su una sessione la esporta in un solo file, in audio o in video come dice il display di Esporta. Esporta e importa una playlist in JSON, con i tuoi brani e le sessioni. Casuale, ripeti e Mix sono nella barra del player.' },
  },
  {
    id: 'radio', tab: 'radio', mode: 'ascolta', show: '#radio-start',
    title: { en: 'Radio', it: 'Radio' },
    what: { en: 'A radio that never ends: a director writes new songs in the styles you pick and plays them one after another, building each one while it plays.', it: 'Una radio senza fine: un regista scrive brani nuovi negli stili che scegli e li passa uno dopo l\'altro, costruendo ognuno mentre suona.' },
    how: { en: 'Pick an artist or the styles, set the knobs, press [On air]. [Pause], [Skip], [Save] the song on air, [Open in Compose].', it: 'Scegli un artista o gli stili, regola le manopole, premi [In onda]. [Pausa], [Salta], [Salva] il brano in onda, [Apri in Componi].' },
    parts: [
      {
        id: 'panel', title: { en: 'Panel', it: 'Pannello' },
        what: { en: 'Artist, styles, chaos, energy, complexity and narrator voice are the character of the radio.', it: 'Artista, stili, caos, energia, complessità e voce narratore sono il carattere della radio.' },
        know: { en: 'They apply from the next song prepared: the next song is written when the one on air reaches 40 %. [Length] (As the style, Short, Medium, Long, Exact) sets the length you hear of the next songs, growth included: a growing song grows inside it, even with an artist who grows freely; a free growth in the Custom profile turns it off. Touching a knob while an artist is chosen switches to Custom. The dice draw a random artist (keep it with Keep), a random mix of styles from different genres or a genre with its styles, one knob or all of them (in range or anywhere), and new sounds: other instruments and kits in the same styles. [Compilation] changes artist, genre, styles and knobs on its own (every song, or every 2 to 4 songs; the two lamps show which); [⚙ Setup] sets the genres, artists, random artists and knob ranges it may use, saved as presets. [Material], next to the knobs and in the setup, says where the parts of the next songs come from: the patterns as written, varied patterns (complexity sets how much they change), composed parts, or each style\'s choice (Mix). It applies from the next song and Replay keeps it; Settings → Radio holds the one the radio starts from.', it: 'Valgono dal prossimo brano preparato: il brano dopo viene scritto quando quello in onda è al 40 %. [Durata] (Come lo stile, Breve, Media, Lunga, Esatta) fissa la durata che senti dei prossimi brani, crescita compresa: un brano che cresce cresce dentro, anche con un artista che cresce libero; la crescita libera nel profilo Personalizzato la toglie. Toccare una manopola con un artista scelto passa a Personalizzato. I dadi pescano un artista casuale (lo tieni con Tieni), un mix di stili di generi diversi o un genere con i suoi stili, una manopola o tutte (in range o ovunque) e suoni nuovi: altri strumenti e kit negli stessi stili. [Compilation] cambia da sola artista, genere, stili e manopole (a ogni brano, o ogni 2-4 brani; le due spie dicono quale); [⚙ Configura] sceglie generi, artisti, artisti casuali e range delle manopole entro cui spazia, salvabili come preset. [Materiale], accanto alle manopole e nella configurazione, dice da dove vengono le parti dei prossimi brani: i pattern come sono scritti, pattern variati (la complessità dice quanto cambiano), parti composte, o la scelta di ogni stile (Misto). Vale dal prossimo brano e il Replay lo ricorda; in Impostazioni → Radio c\'è quello da cui parte la radio.' },
      },
      {
        id: 'invent', title: { en: 'Invent a style', it: 'Inventa uno stile' },
        what: { en: 'A new style mixed from the existing ones, to try before keeping. Genre = broad family (Techno); style = precise recipe inside a genre (Berlin techno); artist = invented name that mixes styles. Only styles are invented, never genres.', it: 'Uno stile nuovo mescolato da quelli che esistono, da provare prima di tenerlo. Genere = famiglia ampia (Techno); stile = ricetta precisa dentro un genere (Techno berlinese); artista = nome inventato che mescola stili. Si inventano solo stili, mai generi.' },
        how: { en: 'The die with a spark, [Invent] in the Styles row, makes a style on trial: its chip says on trial and its genre, the line under the chips says which style gave each part. It plays alone from the next song, artist Custom, compilation off. [Keep] saves it among your styles, [Again] invents another one, × goes back to the styles you had.', it: 'Il dado con la scintilla, [Inventa] nella riga Stili, crea uno stile in prova: il suo chip dice in prova e il suo genere, la riga sotto i chip dice da quale stile viene ogni parte. Suona da solo dal prossimo brano, artista Personalizzato, compilation spenta. [Tieni] lo salva tra i tuoi stili, [Ancora] ne inventa un altro, × torna agli stili di prima.' },
        know: { en: 'The style takes the tempo from one existing style and whole parts (drums, bass, harmony, melody, pads, voice) from one or two others, only in pairs that already work in some style (a drum-and-bass groove stays fast, swing only with swinging grooves). The same seed (in the tooltip) gives the same style. Its songs are marked style on trial. A session saved in a playlist during a trial keeps the style inside, so it replays after a discard.', it: 'Lo stile prende il tempo da uno stile esistente e parti intere (batteria, basso, armonia, melodia, tappeti, voce) da uno o due altri, solo in coppie che funzionano già in qualche stile (un groove drum and bass resta veloce, lo swing solo con groove che swingano). Lo stesso seme (nel tooltip) dà lo stesso stile. I suoi brani sono segnati stile in prova. Una sessione salvata in playlist durante una prova tiene lo stile dentro, così si riascolta anche dopo averlo scartato.' },
      },
      {
        id: 'next', title: { en: 'Coming next', it: 'Prossimi cambi' },
        what: { en: 'Under the song on air, the next three bars where something changes: what each step does to which track ("+ Bass", "Kick: variant 1", "Pad: with the others"), and what the voices say there.', it: 'Sotto il brano in onda, le prossime tre battute in cui cambia qualcosa: cosa fa ogni passo e a quale traccia («+ Bass», «Kick: variante 1», «Pad: con gli altri») e cosa dicono le voci in quel punto.' },
        know: { en: 'V:N is the narrator, V:T the voice track; in italics the words you will hear on that bar, as the code says them: a poetic image instead of the step line, nothing when the narrator is off, quiet where the voice track speaks, or the line has no sample. A voice-track line has its own row even where no step falls. Steps that only mark a section change are not listed.', it: 'V:N è il narratore, V:T la voce traccia; in corsivo le parole che sentirai su quella battuta, come le dice il codice: un\'immagine poetica al posto della frase del passo, niente col narratore spento, silenzio dove parla la voce traccia o se la frase non ha il campione. Una frase della voce traccia ha la sua riga anche dove non cade un passo. I passi che segnano solo un cambio di sezione non compaiono.' },
      },
      {
        id: 'console', title: { en: 'Console', it: 'Console' },
        what: { en: 'Changes the song on air at the next phrase: energy up or down; one more or one fewer track of each instrument (see Arrangement by instrument); more or less complex; darker, brighter, dirtier, cleaner, more space, change instrument; change chords or key (Auto, or a progression of the style and a key a fifth up, a fifth down or the relative one, from the [Chords] and [Key] menus); the narrator talks more or less; in the [Voice] group the voice track\'s phrase preset (from the next quiet part) and its voice style (from the next phrase) with one [Apply], and a typed line ([Add a line]: Say now, At the right moment); go to the drop, stay here, extend, end the song.', it: 'Cambia il brano in onda alla frase dopo: energia su o giù; una traccia in più o in meno di ogni strumento (vedi Arrangiamento per strumento); più o meno complesso; più scuro, più chiaro, più sporco, più pulito, più spazio, cambia strumento; cambia accordi o tonalità (Auto, oppure una progressione dello stile e una tonalità una quinta sopra, una quinta sotto o la relativa, dai menu [Accordi] e [Tonalità]); il narratore parla di più o di meno; nel gruppo [Voce] il preset delle frasi della voce traccia (dalla prossima parte tranquilla) e il suo stile della voce (dalla frase dopo) con un solo [Applica], e una frase scritta ([Aggiungi frase]: Dilla ora, Al momento giusto); vai al drop, resta qui, estendi, chiudi il brano.' },
        how: { en: '{↑} {↓} energy, {1} to {8} one more track of an instrument and {Shift}+{1} to {8} one fewer, {+} {-} complexity, {[} {]} darker and brighter, {X} dirtier, {C} cleaner, {S} space, {I} instrument, {H} chords, {K} key, {V} and {Shift}+{V} narrator voice, {G} drop, {R} stay, {L} extend, {E} end, {N} vary, {W} swap. Waiting commands are in [Coming up], ✕ cancels one.', it: '{↑} {↓} energia, da {1} a {8} una traccia in più di uno strumento e {Shift}+{1} a {8} una in meno, {+} {-} complessità, {[} {]} più scuro e più chiaro, {X} più sporco, {C} più pulito, {S} spazio, {I} strumento, {H} accordi, {K} tonalità, {V} e {Shift}+{V} voce narratore, {G} drop, {R} resta qui, {L} estendi, {E} chiudi, {N} varia, {W} scambia. I comandi in attesa sono in [In arrivo], ✕ ne annulla uno.' },
        know: { en: 'A disabled button says why in its tooltip. With the switch on [The whole session], energy, complexity and narrator voice also move the knobs for the next songs, and [Apply] also writes the preset and the voice style into the Voices group (the voice track switch stays as it is). A typed line belongs to the song on air: at most 12 words, queued with ✕ until it sounds, the narrator quiet on its bars. With [The whole session] the instruments\' [+] and [−], their locks, saved patterns and Part harmony also apply to the next songs where they can (a [+] gives each later song one more track of that instrument, a lock holds it from the moment it first plays there); the queue marks them "for the session", and ✕ takes them out until the next song starts. Vary, Swap and the riser are for the song on air only. The scope says how long a choice lasts, the lock whether the director may change it: this song and open, the director may still change it; this song and closed, it stays as set until the song ends; the whole session and open, it comes back in each song and the director is free there; the whole session and closed, it comes back and stays as set.', it: 'Un pulsante spento dice perché nel suo tooltip. Con l\'interruttore su [Vale per tutta la diretta], energia, complessità e voce narratore spostano anche le manopole per i brani dopo, e [Applica] scrive preset e stile della voce anche nel gruppo Voci (l\'interruttore della voce traccia resta com\'è). Una frase scritta appartiene al brano in onda: al massimo 12 parole, in coda con ✕ finché suona, il narratore tace sulle sue battute. Con [Vale per tutta la diretta] il [+] e il [−] degli strumenti, i loro lucchetti, i pattern salvati e l\'armonia della parte valgono anche nei brani dopo dove possono (un [+] dà a ogni brano dopo una traccia in più di quello strumento, un lucchetto lo tiene dal momento in cui ci entra); la coda li segna "per tutta la diretta" e ✕ li toglie finché non parte il brano dopo. Varia, Scambia e il riser valgono solo per il brano in onda. L\'ambito dice quanto dura una scelta, il lucchetto se il regista può cambiarla: questo brano e aperto, il regista può ancora cambiarla; questo brano e chiuso, resta com\'è fino alla fine del brano; tutta la diretta e aperto, torna in ogni brano e lì il regista è libero; tutta la diretta e chiuso, torna e resta com\'è.' },
        commands: ['energy-up', 'energy-down', 'more-complex', 'less-complex', 'darker', 'brighter', 'dirtier', 'cleaner', 'more-space', 'instrument', 'progression', 'key', 'talk-more', 'talk-less', 'voice', 'voice-sound', 'say-live', 'drop', 'stay', 'extend', 'end'],
      },
      {
        id: 'instruments', title: { en: 'Arrangement by instrument', it: 'Arrangiamento per strumento' },
        what: { en: 'A [−] and a [+] for each instrument the song\'s style can play: kick, beat, bass, texture on the first row, arp, melody, guitar, pad on the second. [+] brings in one more track of that instrument from the next phrase, even when one plays: another sound and pattern from the style, an octave up and a little lower ("Arp 2"); an instrument the song does not have comes from its style. [−] takes away the last track you added. A track you add stays until the song\'s final outro: the director may change its pattern, filter and effects, and it may sit out a break, then it comes back. The lock next to each instrument keeps the director away from it for the rest of the song (open by default). The riser row places a riser, a noise that rises for a few bars and ends on the next change of part: length, up or down, sound; its lock keeps the director\'s own risers out of the song.', it: 'Un [−] e un [+] per ogni strumento che lo stile del brano può suonare: cassa, ritmica, basso, texture nella prima riga, arpeggio, melodia, chitarra, pad nella seconda. [+] porta una traccia in più di quello strumento dalla frase dopo, anche se ne suona già una: un altro suono e un altro pattern dallo stile, un\'ottava sopra e un po\' più bassa ("Arp 2"); uno strumento che il brano non ha arriva dal suo stile. [−] toglie l\'ultima traccia che hai aggiunto. Una traccia che aggiungi resta fino all\'outro finale del brano: il regista può cambiarne pattern, filtro ed effetti, e può saltare un break, poi torna. Il lucchetto accanto a ogni strumento tiene il regista lontano da quello strumento per il resto del brano (di partenza aperto). La riga del riser mette un riser, un fruscio che sale per qualche battuta e finisce sul prossimo cambio di parte: lunghezza, sale o scende, suono; il suo lucchetto tiene fuori dal brano i riser del regista.' },
        how: { en: '{1} to {8} press [+] of the instruments in the console\'s order, {Shift}+{1} to {8} press [−]. A closed lock is lit; the half lock means some of its tracks are locked in the mixer, and a click locks them all. The mixer\'s locks are the same: locking an instrument locks its rows there. The queue says "+ arp (Arp 2)", "bass: locked", "riser 4 bars, up".', it: 'Da {1} a {8} premono il [+] degli strumenti nell\'ordine della console, {Shift}+{1}-{8} il [−]. Un lucchetto chiuso è acceso; il mezzo lucchetto vuol dire che alcune sue tracce sono bloccate nel mixer, e un clic le blocca tutte. I lucchetti del mixer sono gli stessi: bloccare uno strumento blocca le sue righe lì. La coda dice "+ arpeggio (Arp 2)", "basso: bloccato", "riser 4 battute, sale".' },
        know: { en: 'Up to 12 tracks play at once; then [+] is off. Past the recommended count (kick 1, beat 2, bass 2, the others 3) the count badge turns orange and a line says it, but the track comes in. As tracks add up the song plays each a little lower, so the output keeps its room; a volume you set in the mixer stays as set. A lock never blocks you: your [+], [−], Vary, Swap and sound commands still reach a locked instrument, and a locked drum still sits out breaks and the charge before a drop, then comes back at the drop with its sound and pattern; other locked instruments play through. Sessions saved before, with the old buttons for drums and lead, replay as they were heard.', it: 'Suonano al massimo 12 tracce insieme; poi [+] è spento. Oltre i valori consigliati (cassa 1, ritmica 2, basso 2, gli altri 3) il contatore diventa arancione e una riga lo dice, ma la traccia entra. Man mano che le tracce aumentano il brano le suona un po\' più basse, così l\'uscita tiene il suo margine; un volume scelto nel mixer resta com\'è. Un lucchetto non blocca mai te: i tuoi [+], [−], Varia, Scambia e i comandi del suono arrivano anche a uno strumento bloccato, e una batteria bloccata esce comunque nei break e nella carica prima di un drop e torna al drop con il suo suono e il suo pattern; gli altri strumenti bloccati suonano anche lì. Le sessioni salvate prima, con i vecchi pulsanti per batteria e melodia, si riascoltano come erano.' },
        commands: ['more', 'less', 'lock-part', 'unlock-part', 'riser', 'add', 'remove'],
      },
      {
        id: 'saved', title: { en: 'Add a saved pattern', it: 'Aggiungi un pattern salvato' },
        what: { en: 'Your saved patterns (Patterns tab, Save as pattern in Compose) in the song on air: the ones that fit it, by instrument and meter, whatever their styles. Folded, one row each with a small drawing, the instrument and a listen button; open, cards with the drawing, instrument, key, tempo and styles, [Add as new track] and [Replace] with the track it takes the place of.', it: 'I tuoi pattern salvati (scheda Pattern, Salva come pattern in Componi) nel brano in onda: quelli che vanno bene, per strumento e metro, qualunque siano i loro stili. Chiuso, una riga ciascuno con un piccolo disegno, lo strumento e un pulsante per ascoltare; aperto, schede con il disegno, strumento, tonalità, tempo e stili, [Aggiungi come traccia nuova] e [Sostituisci] con la traccia di cui prende il posto.' },
        how: { en: 'Open it with [Add a saved pattern]. The headphones play the pattern alone, in the song\'s key and tempo, while the radio goes on 12 dB lower; press again, or another one, to stop. [Add as new track] brings it in from the next phrase with its own sound; [Replace] puts it in place of the chosen track, which keeps its sound. The queue says "+ My bassline (Bass 2)" or "My melody in place of Lead". With more than 8 that fit, a toolbar finds one: P goes to the search (name, instrument or style; Esc clears it, Esc again leaves it, the down arrow goes to the first pattern), [Fit this song] keeps the ones of the song\'s style or with none at a close tempo, [Style] and [Sort] (As in Patterns, the order you saved them, like the Patterns tab; Recent; Most used; Name; Closest tempo), and the instrument chips. With nothing set they are grouped by instrument, 4 each and [Show all (n)]; a group header folds it. The list scrolls in a box of its own, and keeps its place, the search and the focus while the song plays.', it: 'Aprilo con [Aggiungi un pattern salvato]. Le cuffie suonano il pattern da solo, nella tonalità e nel tempo del brano, mentre la radio va avanti 12 dB più bassa; premi di nuovo, o un altro, per fermarlo. [Aggiungi come traccia nuova] lo porta dalla frase dopo col suo suono; [Sostituisci] lo mette al posto della traccia scelta, che tiene il suo suono. La coda dice "+ Il mio basso (Bass 2)" o "La mia melodia al posto di Lead". Con più di 8 pattern adatti, una barra aiuta a trovarne uno: P va alla ricerca (nome, strumento o stile; Esc la svuota, di nuovo Esc ne esce, la freccia giù va al primo pattern), [Adatti al brano] tiene quelli dello stile del brano o senza stile a un tempo vicino, [Stile] e [Ordina] (Come nei Pattern, l\'ordine in cui li hai salvati, come la scheda Pattern; Recenti; Più usati; Nome; Tempo vicino), e i chip degli strumenti. Senza filtri sono raggruppati per strumento, 4 per gruppo e [Mostra tutti (n)]; l\'intestazione di un gruppo lo chiude. L\'elenco scorre in un riquadro suo e tiene il punto, la ricerca e il cursore mentre il brano suona.' },
        know: { en: 'A pattern written in degrees or chords follows the song\'s key and chords; one written in fixed notes moves to the song\'s key; a chromatic melody keeps its mode. It plays at the song\'s tempo: a card warns when that is much faster or slower than its own. The patterns that do not fit are counted below. The command keeps a copy of the pattern, so Replay sounds the same even after you change or delete it. A pattern added as a new track stays like a track added with [+]. Each [Add as new track], [Replace] and Add to song from the Patterns tab counts as a use (a listen does not): the cards show "used 4 times · 5 days ago", and the counts go in the backup.', it: 'Un pattern scritto in gradi o in accordi segue la tonalità e gli accordi del brano; uno scritto in note fisse si sposta nella tonalità del brano; una melodia cromatica tiene il suo modo. Suona al tempo del brano: una scheda avvisa quando è molto più veloce o più lento del suo. I pattern che non vanno bene sono contati sotto. Il comando tiene una copia del pattern, così il Replay suona uguale anche se lo cambi o lo cancelli. Un pattern aggiunto come traccia nuova resta come una traccia aggiunta col [+]. Ogni [Aggiungi come traccia nuova], [Sostituisci] e Aggiungi al brano dalla scheda Pattern conta come un uso (un ascolto no): le schede dicono "usato 4 volte · 5 giorni fa", e i conteggi vanno nel backup.' },
        commands: ['pattern'],
      },
      {
        id: 'vary', title: { en: 'Vary and Swap', it: 'Varia e Scambia' },
        what: { en: 'New material for one part of the song on air, from the next phrase. [Vary] composes new notes for the part, in the song\'s key and chords, with the same sound; a pad keeps the chords and changes rhythm, register and voicing. [Swap] gives the part another ready part instead: a preset of the style or one of your saved patterns that fits, never composed. When [+] brings in an instrument the song has not played yet, or [More complex] brings in a new track, its part is composed for the song too.', it: 'Materiale nuovo per una parte del brano in onda, dalla frase dopo. [Varia] compone note nuove per la parte, nella tonalità e negli accordi del brano, con lo stesso suono; un pad tiene gli accordi e cambia ritmo, registro e voicing. [Scambia] dà invece alla parte un\'altra parte pronta: un preset dello stile o un tuo pattern salvato che va bene, mai composta. Quando [+] porta uno strumento che il brano non ha ancora suonato, o [Più complesso] porta una traccia nuova, anche la sua parte viene composta per il brano.' },
        how: { en: 'Pick the part under [Parts] (lead, bass, arp, pad, guitar; lead by default) and, with several tracks of it, the [Track]: Auto (the one changed least recently) or one by name ("Arp 2"); then [Vary] ({N}) or [Swap] ({W}). The command waits in [Coming up] as "Vary arp (Arp 2)" with its bar; ✕ cancels it. The track goes back to Auto when it stops playing.', it: 'Scegli la parte sotto [Parti] (melodia, basso, arpeggio, pad, chitarra; di partenza la melodia) e, con più tracce di quella parte, la [Traccia]: Auto (quella cambiata meno di recente) o una per nome ("Arp 2"); poi [Varia] ({N}) o [Scambia] ({W}). Il comando aspetta in [In arrivo] come "Varia arpeggio (Arp 2)" con la sua battuta; ✕ lo annulla. La traccia torna su Auto quando smette di suonare.' },
        know: { en: 'A button is off, with the reason in its tooltip, when that part does not play at the next phrase, or (Swap) when no other ready part fits. The density curve, energy and complexity shape what is composed: fewer notes at low density, higher with more energy, more varied with more complexity. Vary always composes, whatever the material; Replay plays the same notes. [Part harmony] ({A}) changes how the same part sits on the chords, with its [Treatment]: in thirds (a melody, a bass in degrees, an arp), an octave up or down, chord colour (sevenths, pads and guitars only), another inversion; Auto picks one the track has not just had, and the queue says which. The part stays in the song\'s key and chords.', it: 'Un pulsante è spento, con il motivo nel tooltip, quando quella parte non suona alla frase dopo, o (Scambia) quando nessun\'altra parte pronta va bene. La curva di densità, l\'energia e la complessità danno forma a ciò che viene composto: meno note con poca densità, più in alto con più energia, più varie con più complessità. Varia compone sempre, qualunque sia il materiale; il Replay suona le stesse note. [Armonia della parte] ({A}) cambia come la stessa parte sta sugli accordi, col suo [Trattamento]: in terze (una melodia, un basso in gradi, un arpeggio), un\'ottava sopra o sotto, colore degli accordi (settime, solo pad e chitarre), un altro rivolto; Auto ne sceglie uno che la traccia non ha appena avuto, e la coda dice quale. La parte resta nella tonalità e negli accordi del brano.' },
        commands: ['vary', 'swap', 'voicing'],
      },
      {
        id: 'curves', title: { en: 'Curves', it: 'Curve' },
        what: { en: 'Energy is the main curve: the director writes the song to follow it. Under [Details], density, brightness, tension and narrator voice are detail curves of the song on air.', it: 'L\'energia è la curva principale: il regista scrive il brano per seguirla. Sotto [Dettagli], densità, luminosità, tensione e voce narratore sono curve di dettaglio del brano in onda.' },
        how: { en: 'Drag a square of a part still to come; ↺ makes a detail curve automatic again. Hover a curve to see every value of that part.', it: 'Trascina un quadratino di una parte che deve ancora venire; ↺ rimette automatica una curva di dettaglio. Passa col mouse su una curva per vedere tutti i valori di quella parte.' },
        know: { en: 'Tension of 70 or more on the part before a drop builds a charge that the drop releases. Energy wins when two targets clash.', it: 'Una tensione di 70 o più sulla parte prima di un drop costruisce una carica che il drop scarica. Quando due obiettivi si scontrano vince l\'energia.' },
        commands: ['curve', 'curve-reset'],
      },
      {
        id: 'mixer', title: { en: 'Mixer', it: 'Mixer' },
        what: { en: 'One row per track playing: volume, mute, lock (the director stops changing that track; the same lock as its instrument\'s in the Arrangement group) and ♪ to change its instrument.', it: 'Una riga per ogni traccia che suona: volume, muto, lucchetto (il regista smette di cambiare quella traccia; è lo stesso lucchetto del suo strumento nel gruppo Arrangiamento) e ♪ per cambiarne lo strumento.' },
        know: { en: 'Volume and mute apply on the next bar and stay for the rest of the song.', it: 'Volume e muto valgono dalla battuta dopo e restano per il resto del brano.' },
        commands: ['volume', 'mute', 'unmute', 'lock', 'unlock'],
      },
      {
        id: 'transitions', title: { en: 'Transitions and harmony', it: 'Transizioni e armonia' },
        what: { en: 'How one song becomes the next: mix, morph, echo, break, interlude or cut. Harmony "compatible" keeps the next song a fifth away and within 12 BPM; "free" lets it go anywhere.', it: 'Come un brano diventa il successivo: mix, morph, eco, break, interludio o taglio. Armonia "compatibile" tiene il brano dopo a una quinta e entro 12 BPM; "libera" lo lascia andare dove vuole.' },
        how: { en: 'The [Transitions] and [Harmony] menus: "the artist\'s" follows the artist\'s taste.', it: 'I menu [Transizioni] e [Armonia]: "dell\'artista" segue i gusti dell\'artista.' },
      },
      {
        id: 'profile', title: { en: 'Profile and code on air', it: 'Profilo e codice in onda' },
        what: { en: 'How the generated songs grow and how their code looks. As the artist and style say: songs of the live coder styles grow like a live coder, the others build in blocks. Classic, Crescendo or Live coder: one profile for every generated song, with any artist, compilation or style. Custom: the same controls as Compose (build, growth, duration, growth shape, code view, generator, comments, technical functions, title, lit notes, line breaks, human typing, mistakes, narrator voice).', it: 'Come crescono i brani generati e come si vede il loro codice. Come l\'artista e lo stile: i brani degli stili live coder crescono come un live coder, gli altri a blocchi. Classico, Crescendo o Live coder: un profilo per ogni brano generato, con qualsiasi artista, compilation o stile. Personalizzato: gli stessi controlli di Componi (andamento, crescita, durata, forma della crescita, vista del codice, generatore, commenti, funzioni tecniche, titolo, note accese, a capo, scrittura umana, errori, voce narrante).' },
        how: { en: 'The [Profile] menu next to [Transitions] and [Harmony]; with Custom, open [Custom profile] to set its controls, close it to see them in one line. [Incoming song] says whether the next song shows in the code panel during a transition.', it: 'Il menu [Profilo] accanto a [Transizioni] e [Armonia]; con Personalizzato apri [Profilo personalizzato] per sceglierne i controlli, chiudilo per vederli in una riga. [Brano in arrivo] dice se il brano dopo si vede nel pannello del codice durante una transizione.' },
        know: { en: 'It applies from the next song prepared and the session remembers it, so Replay grows the same songs. In Custom, the options that change only how the code looks (comments, technical functions, title, lit notes, line breaks, human typing, mistakes) apply at once, to the song on air from its next code edit, and the sound does not change; a replay shows them as set when it starts. For a whole session of live coding: Live coder here, the Live coder compilation preset, or the artist Cursor Bloom. The code panel shows the song on air in its own profile\'s view; a growing song coming in plays hidden, from its full code, and appears whole when it goes on air (by profile: a Classic song shows, as before). The card of the song on air shows its profile and, for a Live coder song, its growth shape. Sessions saved before songs grew on air replay in blocks, as they were heard. A command on a growing song is its next waypoint: what has played stays, and small typed moves (a line in or out, notes a few at a time, a knob) lead to the song as steered, from the first boundary that leaves time to type them (the queue shows that bar). Vary and Swap edit the notes of the line, mute types the _ of _$:, a volume shows as .gain() on the line, End takes the lines out one at a time before the outro.', it: 'Vale dal prossimo brano preparato e la sessione lo ricorda, così il Replay fa crescere gli stessi brani. In Personalizzato, le opzioni che cambiano solo come si vede il codice (commenti, funzioni tecniche, titolo, note accese, a capo, scrittura umana, errori) valgono subito, sul brano in onda dalla sua prossima modifica del codice, e il suono non cambia; un Replay le mostra come sono scelte quando parte. Per una sessione intera di live coding: Live coder qui, il preset Live coder della compilation, o l\'artista Cursor Bloom. Il pannello del codice mostra il brano in onda con la vista del suo profilo; un brano che cresce in arrivo suona nascosto, dal suo codice completo, e appare intero quando va in onda (secondo il profilo: un brano Classico si vede, come prima). La scheda del brano in onda mostra il profilo e, per un brano Live coder, la forma della crescita. Le sessioni salvate prima che i brani crescessero in onda si riascoltano a blocchi, come si sono sentite. Un comando su un brano che cresce è la sua prossima tappa: quello che è già suonato resta, e piccole mosse scritte (una riga che entra o esce, le note poche alla volta, una manopola) portano al brano guidato, dal primo confine che lascia il tempo di scriverle (la coda mostra quella battuta). Varia e Scambia modificano le note della riga, il muto scrive il _ di _$:, un volume compare come .gain() sulla riga, Chiudi toglie le righe una alla volta prima del finale.' },
      },
      {
        id: 'recording', title: { en: 'Recording', it: 'Registrazione' },
        what: { en: 'Records the radio to an audio file, with a track list and the session recipe.', it: 'Registra la radio in un file audio, con la scaletta e la ricetta della sessione.' },
        how: { en: '[Record] starts, press again to stop and download. The display next to it switches between audio and video; the video has the same track list. [⬇ Export] makes a file faster than real time, audio or video: up to now, the next N songs, a length in minutes (exact, with a fade at the end) or a clip of a few seconds composed to last exactly that, with track list and recipe. The gear beside it opens the video direction. [Record from the start] plays the session again from its first song and records it.', it: '[Registra] parte, premi di nuovo per fermare e scaricare. Il display accanto passa da audio a video; il video ha la stessa scaletta. [⬇ Esporta] crea un file più veloce del tempo reale, audio o video: fino a ora, i prossimi N brani, una durata in minuti (esatta, con una sfumatura alla fine) o una clip di pochi secondi composta per durare esattamente quelli, con scaletta e ricetta. L\'ingranaggio accanto apre la regia del video. [Registra dall\'inizio] rifà la sessione dal primo brano e la registra.' },
        know: { en: 'Pausing leaves no gap in the file. The format (WAV or Opus) is in the settings.', it: 'La pausa non lascia buchi nel file. Il formato (WAV o Opus) è nelle impostazioni.' },
      },
      {
        id: 'extend', title: { en: 'Extend', it: 'Estendi' },
        what: { en: 'Makes the song on air longer, a block at a time (the button says how long), before its ending: a new stretch in the song\'s character, then the outro and the transition as planned.', it: 'Allunga il brano in onda, un blocco alla volta (il pulsante dice quanto), prima del finale: un tratto nuovo nel carattere del brano, poi outro e transizione come previsto.' },
        know: { en: 'No limit. It switches off once the transition to the next song plays. The card shows the total added.', it: 'Nessun limite. Si spegne quando la transizione al brano dopo sta già suonando. La card mostra il totale aggiunto.' },
      },
      {
        id: 'continue', title: { en: 'Continue a song in the radio', it: 'Continua un brano in radio' },
        what: { en: 'A song from Compose or the Songs tab becomes the first song of a new session: it plays to its end, then a transition leads into the radio, in the styles closest to it and in a compatible key and tempo.', it: 'Un brano da Componi o dai Brani diventa il primo brano di una diretta nuova: suona fino alla fine, poi una transizione porta nella radio, negli stili più vicini e in tonalità e tempo compatibili.' },
        how: { en: '[▶ Continue in radio] in Compose (from the bar you are at) or on a song card (from the start).', it: '[▶ Continua in radio] in Componi (dalla battuta in cui sei) o sulla card di un brano (dall\'inizio).' },
        know: { en: 'Your song is not the director\'s: console, curves and Extend apply from the next song. Replay plays your song again too.', it: 'Il tuo brano non è del regista: console, curve ed Estendi valgono dal brano dopo. Riascolta rifà anche il tuo brano.' },
      },
      {
        id: 'seed', title: { en: 'Seed and replay', it: 'Seme e Riascolta' },
        what: { en: 'Same seed and same settings give the same songs. The seed of the session is shown in its field.', it: 'Stesso seme e stesse impostazioni danno gli stessi brani. Il seme della sessione è nel suo campo.' },
        how: { en: '[Replay] plays the session again from its seed, with the same console moves, curve edits and extensions. [+ Playlist] next to the controls, or on a session of the History, keeps the session in a playlist.', it: '[Riascolta] rifà la sessione dal suo seme, con le stesse mosse della console, modifiche alle curve ed estensioni. [+ Playlist] accanto ai comandi, o su una sessione della Cronologia, tiene la sessione in una playlist.' },
      },
    ],
    // what changes the song on air, what changes the next songs
    scope: [
      { what: { en: 'Panel, transitions, harmony', it: 'Pannello, transizioni, armonia' }, now: { en: 'no', it: 'no' }, next: { en: 'yes, from the next song prepared', it: 'sì, dal prossimo brano preparato' } },
      { what: { en: 'Console', it: 'Console' }, now: { en: 'yes, at the next phrase', it: 'sì, alla frase dopo' }, next: { en: 'energy, complexity and voice with "the whole session"', it: 'energia, complessità e voce con "tutta la diretta"' } },
      { what: { en: 'Curves, mixer, extend', it: 'Curve, mixer, estendi' }, now: { en: 'yes', it: 'sì' }, next: { en: 'no (they start later after an extension)', it: 'no (dopo un\'estensione partono più tardi)' } },
      { what: { en: 'Pause, skip, record', it: 'Pausa, salta, registra' }, now: { en: 'right away', it: 'subito' }, next: { en: 'no', it: 'no' } },
    ],
  },
  {
    id: 'artists', tab: 'artisti', mode: 'lab', show: '#tab-artisti',
    title: { en: 'Artists', it: 'Artisti' },
    what: { en: 'The artists who make the radio\'s music: each one has favourite styles, values, quirks and transitions, so every song differs even from the same artist.', it: 'Gli artisti che fanno la musica della radio: ognuno ha stili preferiti, valori, manie e transizioni, così ogni brano è diverso anche dallo stesso artista.' },
    how: { en: 'Open an artist to see the sheet. [New artist] makes your own. [♪ New song] on a sheet opens Compose with a new song by that artist, the New song panel open with the artist picked. [Random artist] makes one with a name, a face and tastes: keep it, try again or discard it.', it: 'Apri un artista per vedere la scheda. [Nuovo artista] ne crea uno tuo. [♪ Nuovo brano] sulla scheda apre Componi con un brano nuovo di quell\'artista, con il pannello Nuovo brano aperto e l\'artista scelto. [Artista casuale] ne crea uno con nome, faccia e gusti: tienilo, riprova o scartalo.' },
    know: { en: 'Your artists stay in this browser: export them to keep them.', it: 'I tuoi artisti restano in questo browser: esportali per tenerli.' },
  },
  {
    id: 'styles', tab: 'stili', mode: 'lab', show: '#tab-stili',
    title: { en: 'Styles', it: 'Stili' },
    what: { en: 'The recipes the radio and the artists write songs from: tempo, instruments, patterns, chords, voice, and the genre the style belongs to.', it: 'Le ricette da cui la radio e gli artisti scrivono i brani: tempo, strumenti, pattern, accordi, voce, e il genere a cui lo stile appartiene.' },
    how: { en: 'Open a style to see how it is made. [Duplicate] a built-in one to change it, or [New style]. [A random style in the radio] plays one you did not pick. [Invent a style] shows a new style in a card: where each part comes from, its genre and the closest style; [Listen in the radio] tries it in the radio, [Again] invents another, [Keep] saves it, [Discard] drops it.', it: 'Apri uno stile per vedere come è fatto. [Duplica] uno incluso per cambiarlo, o [Nuovo stile]. [Uno stile a caso in radio] ne fa suonare uno che non hai scelto. [Inventa uno stile] mostra uno stile nuovo in una scheda: da dove viene ogni parte, il suo genere e lo stile più vicino; [Ascolta in radio] lo prova in radio, [Ancora] ne inventa un altro, [Tieni] lo salva, [Scarta] lo toglie.' },
    know: { en: 'Your styles stay in this browser: export them to keep them. A kept invented style has the Invented badge and its origin; after an edit it reads Invented, edited. It works like any of your styles: artists, the New song panel and the compilation can use it.', it: 'I tuoi stili restano in questo browser: esportali per tenerli. Uno stile inventato tenuto ha il badge Inventato e la sua origine; dopo una modifica diventa Inventato, modificato. Funziona come ogni tuo stile: lo usano gli artisti, il pannello Nuovo brano e la compilation.' },
  },
  {
    id: 'genres', tab: 'generi', mode: 'lab', show: '#tab-generi .genre-card',
    title: { en: 'Genres', it: 'Generi' },
    what: { en: 'One card per genre: its styles, how many songs it has, the artists who love it.', it: 'Una card per genere: i suoi stili, quanti brani ha, gli artisti che lo amano.' },
    how: { en: 'Tap a style to open it. [▶ Listen in the radio] starts the radio in that genre; [See the songs] opens Songs filtered on it. [A random genre in the radio] picks one for you. [Invent a style of this genre] makes a new style that belongs to that genre and tries it in the radio: genres are never invented.', it: 'Tocca uno stile per aprirlo. [▶ Ascolta in radio] fa partire la radio in quel genere; [Vedi i brani] apre Brani filtrata su quel genere. [Un genere a caso in radio] ne sceglie uno per te. [Inventa uno stile di questo genere] crea uno stile nuovo che appartiene a quel genere e lo prova in radio: i generi non si inventano.' },
  },
  {
    id: 'sounds', tab: 'suoni', mode: 'lab', show: '#sounds',
    title: { en: 'Sounds', it: 'Suoni' },
    what: { en: 'Every sound Strudel has loaded: drum machines, instruments, samples, synths and your own samples.', it: 'Tutti i suoni caricati da Strudel: drum machine, strumenti, campioni, synth e i tuoi campioni.' },
    how: { en: 'Click to hear one; [Use] puts it in the selected track of Compose. In the Pads view, keys play the pads. On an instrument or a synth, [Try on a pattern] plays it on a pattern of its kind in the Patterns tab.', it: 'Clic per ascoltarne uno; [Usa] lo mette nella traccia selezionata di Componi. Nella vista Pad i tasti suonano i pad. Su uno strumento o un synth, [Prova su un pattern] lo fa suonare su un pattern del suo tipo nella scheda Pattern.' },
    parts: [{
      id: 'fm-lab', title: { en: 'FM sounds', it: 'Suoni FM' },
      what: { en: 'The FM category holds one card for each FM sound the generator composes: Bell, Reese, Growl, Dirty, Electric piano, Metal, Sub, Organ. FM is one wave modulating another: the more FM, the richer and harsher the sound. Each card shows four drawings of its wave at FM 0, 1, 2 and 3 and, while it plays, a scope of its own sound.', it: 'La categoria FM ha una scheda per ogni suono FM che il generatore compone: Campana, Reese, Ringhio, Sporco, Piano elettrico, Metallo, Sub, Organo. FM è un\'onda che ne modula un\'altra: più FM, più il suono è ricco e aspro. Ogni scheda mostra quattro disegni della sua onda a FM 0, 1, 2 e 3 e, mentre suona, un oscilloscopio del suo suono.' },
      how: { en: 'The headphones play a card on its own; press again to stop. Pick how to listen: [Phrase] (the card\'s part), [Held note] (one long note per bar) or [FM rise] (one note repeated while the FM climbs over 4 bars); the line under them says what each plays. [FM amount] redraws the wave at once and changes the sound from the next bar; in the hardware theme it is a fader. [Use in track] puts the card\'s wave and FM on the bass, arpeggio, hook or pad track selected in Compose; [Copy] copies its code line.', it: 'Le cuffie fanno suonare una scheda da sola; premi di nuovo per fermarla. Scegli come ascoltare: [Frase] (la parte della scheda), [Nota tenuta] (una nota lunga per battuta) o [Salita FM] (una nota ripetuta mentre la FM sale in 4 battute); la riga sotto dice cosa suona ognuno. [Quantità FM] ridisegna subito l\'onda e cambia il suono dalla battuta dopo; nel tema hardware è un fader. [Usa nella traccia] mette l\'onda e la FM della scheda sulla traccia di basso, arpeggio, hook o pad selezionata in Componi; [Copia] copia la sua riga di codice.' },
      know: { en: 'A card never changes the song or the player bar: with the song stopped it plays alone at its own tempo, with the song playing it joins on the next bar at the song\'s tempo. One card plays at a time, and it stops when you leave the tab or an export or recording starts. Phrase is chosen each time the page opens; the mode stays when you pick another card, and picking another card while one plays switches to it. The drawing of Dirty is indicative: its modulator is noise.', it: 'Una scheda non cambia mai il brano né la barra del player: a brano fermo suona da sola al suo tempo, a brano in corsa entra alla battuta dopo al tempo del brano. Suona una scheda alla volta, e si ferma quando lasci la scheda o parte un export o una registrazione. Frase è scelto ogni volta che si apre la pagina; il modo resta quando scegli un\'altra scheda, e sceglierne un\'altra mentre una suona passa a quella. Il disegno di Sporco è indicativo: la sua modulante è rumore.' },
    }],
  },
  {
    id: 'patterns', tab: 'pattern', mode: 'lab', show: '#patterns',
    title: { en: 'Patterns', it: 'Pattern' },
    what: { en: 'What a part plays, apart from any song: melodies, basslines, arpeggios, chords, grooves and riffs, the app\'s and your own, each with a small preview (notes against time, or a step grid for grooves).', it: 'Quello che suona una parte, fuori da un brano: melodie, linee di basso, arpeggi, accordi, groove e riff, quelli dell\'app e i tuoi, ognuno con una piccola anteprima (note nel tempo, o una griglia di passi per i groove).' },
    how: { en: 'Search, or filter by kind and by [Built-in] or [Mine]. Pick a pattern and press [Play in a loop]: change the sound, key, chords, mode and tempo, or turn on [Simple beat under it]; the change plays from the next bar. [New] composes a part of the same kind with the number beside it, the energy and a style, and plays it; on riffs, [Guitar riff] or [Bass riff] says which. New parts stay under New, not saved, also after a reload, until [Save to mine] keeps one or [Discard] drops it; [Discard all] on that strip drops them all. [Add to song] puts the pattern in the song open in Compose, on the next free letter. In Compose, the headphones next to a track\'s preset open its pattern here with the track\'s sound, key and tempo, and [Save as pattern] keeps it among yours.', it: 'Cerca, o filtra per tipo e per [Inclusi] o [Miei]. Scegli un pattern e premi [Suona in loop]: cambia suono, tonalità, accordi, modo e tempo, o accendi [Battito semplice sotto]; la modifica suona dalla battuta dopo. [Nuovo] compone una parte dello stesso tipo col numero accanto, l\'energia e uno stile, e la fa suonare; sui riff, [Riff di chitarra] o [Riff di basso] dice quale. Le parti nuove restano sotto Nuovi, non salvati, anche dopo aver ricaricato la pagina, finché [Salva tra i miei] non ne tiene una o [Scarta] non la toglie; [Scarta tutti] su quella striscia le toglie tutte. [Aggiungi al brano] mette il pattern nel brano aperto in Componi, sulla prima lettera libera. In Componi, le cuffie accanto al preset di una traccia aprono qui il suo pattern col suono, la tonalità e il tempo della traccia, e [Salva come pattern] lo tiene tra i tuoi.' },
    know: { en: 'Built-in patterns list the styles that use them; a tap opens the style, and a preset in a style\'s sheet opens here. Your patterns can be renamed and deleted (two presses), stay in this browser and go into the backup. The radio may play them in songs of the styles of their tags, or of any style when they have none: on your pattern, the style chips set them, [+ Add a style] adds one and the cross removes it; with none it shows every style. New links the style chosen; Save as pattern links the song\'s styles, or its artist\'s when the song has none. New parts stay in this browser and go into the backup; at most 30 are kept and the oldest goes first. A pattern opened from Compose and not saved goes when you leave the tab. The code of the loop is written with the technical functions of the current profile. Sound, key, chords, tempo and the beat change the loop from the next bar; the tempo follows the slider as it moves. Number, energy and style, under New pattern, only shape [New].', it: 'I pattern inclusi elencano gli stili che li usano; un tocco apre lo stile, e un preset nella scheda di uno stile si apre qui. I tuoi pattern si rinominano e si eliminano (due pressioni), restano in questo browser ed entrano nel backup. La radio può suonarli nei brani degli stili dei loro tag, o di ogni stile se non ne hanno: sul tuo pattern li decidono i chip degli stili, [+ Aggiungi uno stile] ne aggiunge uno e la crocetta lo toglie; senza stili mostra ogni stile. Nuovo collega lo stile scelto; Salva come pattern collega gli stili del brano, o quello del suo artista se il brano non ne ha. Le parti nuove restano in questo browser ed entrano nel backup; se ne tengono al massimo 30 e la più vecchia esce per prima. Un pattern aperto da Componi e non salvato se ne va quando lasci la scheda. Il codice del loop è scritto con le funzioni tecniche del profilo attuale. Suono, tonalità, accordi, tempo e beat cambiano il loop dalla battuta dopo; il tempo segue il cursore mentre si muove. Numero, energia e stile, sotto Pattern nuovo, valgono solo per [Nuovo].' },
  },
  {
    id: 'lessons', tab: 'lezioni', mode: 'lab', show: '#lessons',
    title: { en: 'Strudel lessons', it: 'Lezioni Strudel' },
    what: { en: 'Short steps to learn Strudel, the language the app writes, from the first kick to a full song.', it: 'Passi brevi per imparare Strudel, il linguaggio che l\'app scrive, dal primo colpo di cassa a un brano intero.' },
    how: { en: '[▶ Load and play] puts the example in the editor and starts it; change the code and press {Ctrl}+{Enter}.', it: '[▶ Carica e ascolta] mette l\'esempio nell\'editor e lo fa partire; cambia il codice e premi {Ctrl}+{Enter}.' },
    know: { en: 'For developers and AI agents, the repository has a knowledge base in docs/knowledge/: Strudel basics, one note per concept of the app with its options, real code examples and the decisions taken. Start from docs/knowledge/README.md.', it: 'Per chi sviluppa e per gli agenti AI, il repository ha una base di conoscenza in docs/knowledge/: le basi di Strudel, una nota per ogni concetto dell\'app con le sue opzioni, esempi di codice veri e le decisioni prese. Si parte da docs/knowledge/README.md.' },
  },
  {
    id: 'references', tab: 'riferimenti', mode: 'lab', show: '#refs',
    title: { en: 'References', it: 'Riferimenti' },
    what: { en: 'Where all this comes from and where to go next: Strudel, its docs, the sounds and the people behind them.', it: 'Da dove viene tutto questo e dove andare dopo: Strudel, la sua documentazione, i suoni e le persone dietro.' },
    how: { en: 'Open a link: it opens in a new tab.', it: 'Apri un link: si apre in una nuova scheda.' },
  },
  {
    id: 'settings', tab: 'impostazioni', mode: null, show: '#open-settings',
    title: { en: 'Settings', it: 'Impostazioni' },
    what: { en: 'Options used less often: theme, language, the radio\'s visual and defaults, the export format, the video layout and quality, backup.', it: 'Le opzioni usate meno spesso: tema, lingua, visual e valori della radio, formato di export, layout e qualità dei video, backup.' },
    how: { en: 'The ⚙ gear at the top opens and closes them. [Export everything] saves your songs, playlists, artists, styles, patterns and settings to a file; [Import] brings them into another browser. Library → [Show hidden built-in songs (n)] brings back the app\'s songs you deleted. Advanced → Growth shapes tried (4 to 32, 8 by default) says how many shapes a Live coder growth in Compose tries before it keeps the best one; Try all growth shapes lifts that limit and keeps the first good one or the best one; Random order off tries the shapes in the fixed order of before; Long song from (15 minutes by default) makes a longer grown song try every shape and keep the shortest. The radio follows the first three for sessions started after the change: each Live coder song grows with the default search first and takes the wider one when it is ready in time, and a replay grows each song as it played; Long song from is Compose only. A line above them says how many growth shapes there are. Chooser on air (Normal v1 by default) picks the order of the typed moves when you steer a grown song on the radio, for sessions started after the change; a session replays with the chooser it was played with.', it: 'L\'ingranaggio ⚙ in alto le apre e le chiude. [Esporta tutto] salva in un file brani, playlist, artisti, stili, pattern e impostazioni; [Importa] li porta in un altro browser. Libreria → [Mostra i brani inclusi nascosti (n)] rimette i brani inclusi che hai eliminato. Avanzate → Forme di crescita provate (da 4 a 32, di serie 8) dice quante forme prova una crescita Live coder in Compose prima di tenere la migliore; Prova tutte le forme toglie il limite e tiene la prima buona o la migliore; Ordine casuale spento prova le forme nell\'ordine fisso di prima; Brano lungo da (di serie 15 minuti) fa provare tutte le forme a un brano cresciuto più lungo e tiene il più corto. La radio segue le prime tre per le sessioni avviate dopo la modifica: ogni brano Live coder cresce prima con la ricerca di serie e passa a quella più ampia se è pronta in tempo, e un riascolto cresce ogni brano come è stato suonato; Brano lungo da vale solo in Compose. Una riga sopra dice quante forme di crescita ci sono. Scelta delle mosse in onda (di serie Normale v1) sceglie l\'ordine delle mosse scritte quando guidi un brano cresciuto in radio, per le sessioni avviate dopo la modifica; una sessione si riascolta con la scelta con cui è stata suonata.' },
    know: { en: '[Reset everything] needs two presses. An export longer than ten minutes asks where to save it first, then writes the file while it renders, so even hours of radio fit in one file. More growth shapes can find a growth with fewer rushed steps and take longer; up to twice as many are tried when none is enough, and the radio always uses 8.', it: '[Azzera tutto] vuole due pressioni. Un export più lungo di dieci minuti chiede prima dove salvarlo, poi scrive il file mentre si genera, così anche ore di radio stanno in un file solo. Più forme di crescita possono trovare una crescita con meno passi di corsa e ci mettono di più; se nessuna basta se ne provano fino al doppio, e la radio ne usa sempre 8.' },
  },
  {
    id: 'code-widgets', tab: 'impostazioni', mode: null, show: '#set-widgets',
    title: { en: 'Code widgets', it: 'Widget nel codice' },
    what: { en: 'Strudel\'s small animated pictures written by the app at the end of some lines of the code, as a live coder would: a scope of the wave, a pianoroll or punchcard of the notes, a spectrum, and, when turned on, a spiral and a pitchwheel. They work in every profile, on the radio and in songs that do not grow. The music does not change.', it: 'I piccoli disegni animati di Strudel scritti dall\'app alla fine di alcune righe del codice, come farebbe un live coder: lo scope dell\'onda, il pianoroll o il punchcard delle note, lo spectrum e, se li accendi, lo spiral e il pitchwheel. Valgono in ogni profilo, in radio e nei brani non in divenire. La musica non cambia.' },
    how: { en: 'Settings → Code widgets → Write widgets [On]. At most at once (3 by default) is a ceiling: each section shows from 1 up to that many. Slot order says which tracks get one first (bass, lead, drums, arp, hats, pad, then effects and voice); Secondary widgets (25% by default) gives a line another widget now and then, for variety. Muted lines keep their widget, dimmed, only if they return within 16 bars (8, 16, 32 or always). Each widget, each instrument (its main and secondary widgets), the parameters and the sizes have their own section.', it: 'Impostazioni → Widget nel codice → Scrivi i widget [Accesi]. Al massimo insieme (di serie 3) è un tetto: ogni sezione ne mostra da 1 a quel numero. Ordine dei posti dice quali tracce ne prendono uno per prime (basso, lead, batteria, arpeggio, hats, pad, poi effetti e voce); Widget secondari (di serie 25%) dà ogni tanto a una riga un altro widget, per varietà. Le righe mute tengono il widget, attenuato, solo se tornano entro 16 battute (8, 16, 32 o sempre). Ogni widget, ogni strumento (widget principale e secondari), i parametri e le misure hanno la loro sezione.' },
    know: { en: 'The line shows only the short call, such as ._scope(); sizes and the theme\'s colours come from the hidden code. A scope or spectrum draws its line\'s instrument, and the stage still sees it. Code copied to another Strudel plays the same and shows Strudel\'s own sizes. Widget notes Always full draws quiet notes of the pianoroll at full strength, only on screen. The session video\'s scene Visual + code + widgets and the live output\'s views 12 and 13 draw them below their lines, and so do the fragments\' Visual + code + widgets and Code + widgets; the fast video draws them from each line\'s notes and, for scope and spectrum, from their instrument alone (Settings → Video → Real scope and spectrum in the fast video: Automatic falls back to the whole song\'s wave when the export would take more than twice as long).', it: 'La riga mostra solo la chiamata corta, come ._scope(); misure e colori del tema arrivano dal codice nascosto. Uno scope o uno spectrum disegna lo strumento della sua riga, e il palco continua a vederlo. Il codice copiato in un altro Strudel suona uguale e mostra le misure di Strudel. Note dei widget Sempre piene disegna a piena forza le note piano del pianoroll, solo sullo schermo. La scena Visual + codice + widget del video della sessione e le viste 12 e 13 dell\'uscita live li disegnano sotto le loro righe, come le scelte Visual + codice + widget e Codice + widget dei frammenti; il video veloce li disegna dalle note di ogni riga e, per scope e spectrum, dallo strumento da solo (Impostazioni → Video → Scope e spectrum veri nel video veloce: Automatico usa l\'onda del brano intero quando l\'export durerebbe più del doppio).' },
  },
  {
    id: 'fragments', tab: 'brani', mode: 'ascolta', show: '[data-frag]',
    title: { en: 'Fragments', it: 'Frammenti' },
    what: { en: 'Short vertical videos (9:16) cut from a song or a saved session, to share a moment of a longer video. Each one carries the coding-misk logo, a terminal label such as FRAGMENT S0UL·7QX2K #014 with a number that grows, and a glitch at the start and the end. A title and a description come with it, and with every long export too.', it: 'Video brevi verticali (9:16) tratti da un brano o da una sessione salvata, per condividere un momento di un video più lungo. Ognuno porta il logo coding-misk, un\'etichetta da terminale come FRAGMENT S0UL·7QX2K #014 con un numero che cresce, e un glitch all\'inizio e alla fine. Arrivano con un titolo e una descrizione, come ogni export lungo.' },
    how: { en: 'Press [✂ Fragments] on a song card, or [✂] on a session in a playlist. Pick At random (how many and how many seconds) or From – to (for example 12:40 to 13:10), the layout, then [Make]. A radio export can be cut from its recipe file: Settings, Vertical fragments, [Fragments from a recipe file…]. After a save the texts panel lets you copy the title and the description, or draw new ones.', it: 'Premi [✂ Frammenti] sulla card di un brano, o [✂] su una sessione in una playlist. Scegli A caso (quanti e quanti secondi) o Da – a (per esempio da 12:40 a 13:10), il layout, poi [Crea]. Un export della radio si taglia dal suo file ricetta: Impostazioni, Frammenti verticali, [Frammenti da un file ricetta…]. Dopo un salvataggio il pannello dei testi ti fa copiare titolo e descrizione, o rigenerarli.' },
    know: { en: 'Fragments are rendered again from the song, so they match the long video second for second and need no video file. Random fragments prefer the lively parts and are the same for the same seed. Artist names never appear. Settings, Vertical fragments holds the tagline, the line pointing to the full video, the label and its next number, and the glitch. The die beside the tagline gives each fragment its own phrase. The tagline types itself in. The texts beside the menu add tags, hashtags and a category for upload forms.', it: 'I frammenti si rigenerano dal brano, quindi coincidono secondo per secondo con il video lungo e non serve il file video. Quelli a caso preferiscono i punti vivaci e sono uguali con lo stesso seme. I nomi degli artisti non compaiono mai. In Impostazioni, Frammenti verticali ci sono lo slogan, la riga verso il video intero, l\'etichetta e il suo prossimo numero, e il glitch. Il dado accanto allo slogan dà a ogni frammento una frase sua. Lo slogan si scrive da solo, a macchina. I testi accanto al menu aggiungono tag, hashtag e categoria per i moduli di caricamento.' },
  },
  {
    id: 'live', tab: 'impostazioni', mode: null, show: '#set-live',
    title: { en: 'Live output', it: 'Uscita live' },
    what: { en: 'A broadcast window shows only the picture of the session playing in the app, for a capture program such as OBS. A control room in another tab picks the presets (visual, code, soul, with or without the song card), moves between them with a transition, and drives OBS: go live and end, Live and Standby scenes, the picture on air.', it: 'Una finestra di trasmissione mostra solo il quadro della sessione che suona nell\'app, per un programma di cattura come OBS. Una regia in un\'altra scheda sceglie i preset (visual, codice, anima, con o senza scheda del brano), passa dall\'uno all\'altro con una transizione e guida OBS: vai in diretta e termina, scene Live e Standby, il quadro in onda.' },
    how: { en: 'Set OBS up once: Tools, WebSocket Server Settings, Enable (copy the password). Make a scene Live with a capture of the window "coding-misk broadcast" and the browser\'s sound, and a scene Standby with an image, a line of text and a music bed on loop (a playlist of calm songs exported from the Playlists tab). Add the script obs/coding-misk-watchdog.lua of the repository in Tools, Scripts. Then in Settings press [Open the broadcast window] and [Open the control room], and [Connect] there. Presets: click to preview, [⇄ TAKE] or {Enter} to put on air; {1}…{5}, {C} song card, {B} Standby.', it: 'Prepara OBS una volta: Strumenti, Impostazioni server WebSocket, Abilita (copia la password). Crea una scena Live con la cattura della finestra "coding-misk broadcast" e l\'audio del browser, e una scena Standby con un\'immagine, una riga di testo e una musica di sottofondo in loop (una playlist di brani calmi esportata dalla scheda Playlist). Aggiungi lo script obs/coding-misk-watchdog.lua del repository in Strumenti, Script. Poi nelle Impostazioni premi [Apri la finestra di trasmissione] e [Apri la regia], e lì [Collega]. Preset: un clic per l\'anteprima, [⇄ TAKE] o {Invio} per metterlo in onda; {1}…{5}, {C} scheda brano, {B} Attesa.' },
    know: { en: 'Presets 6 to 11 add the song\'s timeline (or a column of the tracks playing); [Future on the timeline] hides what is coming for live build songs. The window keeps drawing when the app\'s tab is behind another, and comes back by itself if the app reloads. If the picture stops for 5 seconds while OBS sends, the script switches to Standby and back to Live when it returns. [Go live] and [End] need two presses. On a Mac, Chrome stops drawing a window covered by others: start it with tools/live-chrome.sh, which also gives coding-misk its own profile so other tabs\' sound stays out.', it: 'I preset da 6 a 11 aggiungono la timeline del brano (o una colonna delle tracce accese); [Futuro sulla timeline] nasconde ciò che arriva per i brani in divenire. La finestra continua a disegnare quando la scheda dell\'app è dietro un\'altra, e torna da sola se l\'app si ricarica. Se il quadro si ferma per 5 secondi mentre OBS trasmette, lo script passa a Standby e torna a Live quando riparte. [Vai in diretta] e [Termina] vogliono due pressioni. Su Mac, Chrome smette di disegnare una finestra coperta da altre: avvialo con tools/live-chrome.sh, che dà anche a coding-misk un profilo suo così l\'audio delle altre schede resta fuori.' },
  },
];

// parts of the page that need no card, with the reason (the check accepts them)
export const GUIDE_EXEMPT = { guida: 'the Guide itself' };

const escHtml = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// a guide text with its marks: [Label] a button, {K} a key
export const guideText = s => escHtml(s).replace(/\[([^\]{}]+)\]/g, '<span class="g-b">$1</span>').replace(/\{([^}]+)\}/g, '<kbd>$1</kbd>');
